const e={id:"s03",unidad:1,semana:3,kind:"aprendizaje",temaGenerador:"Un camino seguro a la escuela",title:"Un camino seguro a la escuela",subtitle:"Rutas, señales, movimiento, comunicación pública y análisis de problemas",icon:"Route",color:"var(--area-ccss)",contexto:"Cada trayecto a la escuela combina caminos, cruces, movimiento de personas y vehículos, señales y mensajes públicos. Esta semana estudiarás esos elementos desde distintas áreas: interpretarás señales, representarás desplazamientos, analizarás causas y efectos de problemas cercanos y diseñarás comunicación visual clara. Una ruta no se considera segura solo por dibujarla o verla una vez: cualquier conclusión dependerá de observaciones concretas, de las condiciones del momento y de la revisión de personas adultas y autoridades responsables.",ejes:["multiculturalidad","equidad","trabajo","seguridad"],media:{id:"s03-portada",kind:"image",title:"Caminos hacia la escuela",aspect:"16:9",alt:"Estudiantes observan desde la entrada de una escuela dos rutas posibles, un cruce, una parada de bus y varias señales comunitarias.",brief:"Ilustración educativa de una comunidad guatemalteca vista desde la entrada de una escuela. Dos rutas peatonales conectan viviendas y una parada de bus con la escuela; se distinguen una acera, un cruce visible, una curva, una calle sin acera y señales comunitarias. Una docente acompaña a estudiantes que anotan observaciones desde un lugar apartado del tránsito. Sin marcas comerciales ni afirmaciones visuales de que una ruta sea totalmente segura. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},badge:{id:"medalla-s03",name:"Analista de rutas",icon:"Route",desc:"Completaste la semana 3 y superaste su reto"},bank:[{fase:"comprobar",areas:["mat"],cnb:["mat:1.2.1"],prompt:"Un patio rectangular mide **18 m** de largo y **11 m** de ancho. ¿Cuál es su perímetro?",type:"number-input",props:{answer:58,unit:"m"},id:"s03-banco-1"},{fase:"comprobar",areas:["l1"],cnb:["l1:5.1.7"],prompt:"¿Cuál oración funciona como acotación en una obra sobre el camino escolar?",type:"choice",props:{options:[{id:"a",text:"(Se detiene antes del cruce y mira hacia ambos lados.)"},{id:"b",text:"MARTA: Esperemos aquí."},{id:"c",text:"El narrador cuenta toda la historia."}],correct:["a"]},id:"s03-banco-2"},{fase:"comprobar",areas:["cnt"],cnb:["cnt:2.3.1"],prompt:"Clasifica cada caso según la vía de secreción descrita.",type:"sort",props:{buckets:[{id:"int",label:"Secreción interna (endocrina)",icon:"HeartPulse"},{id:"ext",label:"Secreción externa (exocrina)",icon:"Droplets"}],items:[{id:"a",text:"El producto entra directamente a la sangre sin pasar por un conducto",bucket:"int"},{id:"b",text:"El producto recorre un conducto hasta la superficie de la piel",bucket:"ext"}]},id:"s03-banco-3"},{fase:"comprobar",areas:["ccss"],cnb:["ccss:3.4.1"],prompt:"Ordena el recorrido económico del café centroamericano.",type:"order",props:{items:[{id:"a",text:"Cultivo y cosecha del café"},{id:"b",text:"Transformación y empaque"},{id:"c",text:"Transporte al puerto"},{id:"d",text:"Exportación a otro continente"}],labels:{start:"Inicio",end:"Destino"}},id:"s03-banco-4"},{fase:"comprobar",areas:["l2"],cnb:["l2:2.1.3"],prompt:"En una noticia sobre asistencia aparecen diez figuras de personas y cuatro están coloreadas. ¿Qué dato comunica la imagen?",type:"choice",props:{options:[{id:"a",text:"Cuatro de cada diez personas asistieron"},{id:"b",text:"Diez de cada cuatro personas asistieron"},{id:"c",text:"Asistieron catorce personas"}],correct:["a"]},id:"s03-banco-5"},{fase:"comprobar",areas:["l3"],cnb:["l3:1.3.3"],prompt:"Read Ana’s three-sentence impression.",type:"reading",props:{genre:"Short report",heading:"A different morning",passage:"This morning I went to school by bus. I saw workers repairing the bridge. I felt surprised.",questions:[{q:"How did Ana go to school?",options:[{id:"a",text:"By bus"},{id:"b",text:"On foot"},{id:"c",text:"By bicycle"}],correct:"a"},{q:"How did she feel?",options:[{id:"a",text:"Surprised"},{id:"b",text:"Angry"},{id:"c",text:"Sleepy"}],correct:"a"}]},id:"s03-banco-6"},{fase:"comprobar",areas:["fc"],cnb:["fc:1.2.3"],prompt:"Relaciona cada situación con el concepto más preciso.",type:"match",props:{pairs:[{id:"a",left:"Creer sin pruebas que un pueblo “no trabaja”",right:"Prejuicio"},{id:"b",left:"Negar un servicio por el idioma de una persona",right:"Discriminación"},{id:"c",left:"Afirmar que todos los integrantes de un grupo son iguales",right:"Estereotipo"}]},id:"s03-banco-7"},{fase:"comprobar",areas:["art"],cnb:["art:2.2.1"],prompt:"Quieres que una flecha blanca aparezca sobre un fondo azul de acuarela. ¿Qué procedimiento aprovecha la técnica de reserva?",type:"choice",props:{options:[{id:"a",text:"Dibujar primero la flecha con crayón blanco y luego aplicar la acuarela azul"},{id:"b",text:"Pintar todo de azul y borrar con agua"},{id:"c",text:"Mezclar pastel seco dentro del vaso de agua"}],correct:["a"]},id:"s03-banco-8"},{fase:"comprobar",areas:["ef"],cnb:["ef:1.4.12"],prompt:"Sin hablar y con el cuerpo quieto, una intérprete fija los ojos en una puerta imaginaria para dirigir allí la atención del público. ¿Qué recurso expresivo usa principalmente?",type:"choice",props:{options:[{id:"a",text:"La mirada"},{id:"b",text:"La trayectoria de carrera"},{id:"c",text:"El pulso musical"}],correct:["a"]},id:"s03-banco-9"},{fase:"comprobar",areas:["pyd"],cnb:["pyd:2.3.1","pyd:2.3.2"],prompt:"¿Qué acción corresponde a un círculo de calidad antes de elegir una solución?",type:"choice",props:{options:[{id:"a",text:"Reunir evidencias, separar causas y efectos y comparar propuestas"},{id:"b",text:"Aceptar la primera idea sin escuchar al grupo"},{id:"c",text:"Instalar cambios en la calle sin consultar a la autoridad"}],correct:["a"]},id:"s03-banco-10"}]},a=JSON.parse('[{"missionId":"s03","version":"cnb-sexto-eb17ff715f5ef3f8","lesson":{"id":"s03-ccss-1","title":"Rutas que conectan intercambios","icon":"Route","minutes":15,"gancho":"Los caminos cambian, pero siguen conectando personas, productos e ideas.","objetivos":["Explicar como las rutas conectan intercambios antiguos y actividades productivas centroamericanas actuales con otros continentes"],"resumen":["Mayas, incas, egipcios y mesopotamicos combinaron caminos, rios, canoas, mensajeros y escritura para comunicar y transportar.","Hoy las actividades productivas centroamericanas incluyen agricultura, industria y servicios.","Rutas terrestres y maritimas conectan productos y servicios de Centroamerica con America del Norte, Europa y Asia.","Comparar antes y hoy muestra una continuidad: las rutas facilitan intercambio, aunque cambien los medios, la escala y los productos."],"media":{"id":"s03-ccss-1-rutas-tiempo","kind":"diagram","title":"Rutas e intercambio antes y hoy","aspect":"16:9","alt":"Dos escenas comparan un camino y una canoa antiguos con una carretera y un puerto centroamericanos actuales.","brief":"Diagrama comparativo 1600x900. A la izquierda, sacbe maya, mensajero a pie y canoa con cargas; a la derecha, finca de cafe, fabrica, camion y puerto con rutas hacia America del Norte, Europa y Asia. Flechas rotuladas intercambio de productos e ideas. No incluir caballos ni carretas en la escena maya. Texto grande, alto contraste, iconos ademas de color y orden de lectura accesible."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:3.3.1","ccss:3.4.1"],"prompt":"Compara como las rutas conectaron intercambio antes y hoy: medios de culturas antiguas y actividades productivas de Centroamerica vinculadas con otros continentes.","type":"explain","props":{"icon":"Route","body":"Los **mayas** usaron sacbeob, canoas, mensajeros y escritura; los **incas**, caminos y chasquis; Egipto aprovecho el Nilo. Hoy **Centroamerica** conecta agricultura, industria y servicios con America del Norte, Europa y Asia mediante carreteras, puertos y rutas maritimas."},"id":"s03-ccss-1-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.3.1","ccss:3.4.1"],"title":"Un mismo problema, medios distintos","prompt":"Relaciona rutas, comunicacion, transporte e intercambio en culturas antiguas y en la Centroamerica actual.","type":"explain","props":{"icon":"GitCompare","body":"**Antes:** un sacbe permitia caminar entre ciudades mayas; una canoa transportaba sal o cacao; un mensajero llevaba informacion. **Hoy:** cafe y cardamomo de la agricultura, textiles de la industria y servicios como transporte salen de Centroamerica hacia otros continentes. La continuidad es la conexion para intercambiar; cambian tecnologia, velocidad y escala."},"id":"s03-ccss-1-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.3.1","ccss:3.4.1"],"title":"Modelo de comparacion","prompt":"Observa como explicar la continuidad entre una ruta antigua y una ruta productiva actual.","type":"worked-example","props":{"icon":"Ship","problem":"Una canoa maya llevaba sal por la costa. Hoy un barco lleva cafe centroamericano hacia Europa.","steps":[{"text":"Medio antiguo: canoa y ruta costera."},{"text":"Actividad actual: agricultura y comercio de cafe por puerto."},{"text":"Continuidad: ambas rutas conectan lugares para intercambiar productos."},{"text":"Cambio: el barco actual recorre otros continentes con mayor capacidad."}],"answer":"Las rutas sostienen intercambio en ambos tiempos, con medios y escalas diferentes."},"id":"s03-ccss-1-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.3.1","ccss:3.4.1"],"prompt":"Con ayuda, relaciona cada medio o actividad con la ruta que permite intercambio.","hint":"Distingue culturas antiguas de actividades centroamericanas actuales.","explain":"Los medios dependen del tiempo y la geografia, pero todos conectan intercambio.","type":"match","props":{"pairs":[{"id":"a","left":"Canoa maya con cacao","right":"Rio o costa antigua"},{"id":"b","left":"Chasqui inca con mensaje","right":"Camino andino antiguo"},{"id":"c","left":"Cafe de Guatemala hacia Europa","right":"Carretera, puerto y ruta maritima actual"},{"id":"d","left":"Servicio del Canal de Panama","right":"Conexion oceanica actual"}]},"id":"s03-ccss-1-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:3.3.1","ccss:3.4.1"],"prompt":"Compara un sacbe maya con una carretera que lleva productos centroamericanos a un puerto.","hint":"Busca continuidad y cambio.","explain":"Ambas rutas conectan intercambio; cambian los vehiculos, la capacidad y el alcance.","type":"choice","props":{"options":[{"id":"a","text":"Ambas conectan lugares para intercambio, aunque cambian medios y escala"},{"id":"b","text":"Solo la carretera moderna conecta personas"},{"id":"c","text":"El sacbe llevaba barcos hasta Asia"}],"correct":["a"]},"id":"s03-ccss-1-5"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:3.3.1","ccss:3.4.1"],"prompt":"Explica de forma independiente una continuidad y un cambio: compara un medio maya, inca o egipcio con una ruta actual que conecta agricultura, industria o servicios de Centroamerica con America del Norte, Europa o Asia. Incluye el intercambio que permite.","type":"short-answer","props":{"minWords":24,"placeholder":"Antes... Hoy... Continuidad... Cambio...","model":"Antes, una canoa maya movia sal por la costa. Hoy, rutas y puertos conectan cafe centroamericano con Europa. Ambas permiten intercambio; cambian alcance y capacidad.","rubric":["Nombre un medio antiguo","Relacione actividad y continente actuales","Explique continuidad y cambio"]},"id":"s03-ccss-1-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:3.3.1","ccss:3.4.1"],"prompt":"Una ruta lleva textiles de una industria centroamericana por carretera y barco hasta America del Norte. ¿Que comparacion con los mensajeros incas es valida?","type":"choice","props":{"options":[{"id":"a","text":"Ambas conexiones trasladan algo entre lugares; hoy cambian medio, carga y distancia"},{"id":"b","text":"Los chasquis transportaban contenedores por mar"},{"id":"c","text":"Las rutas antiguas no permitian intercambio"}],"correct":["a"]},"id":"s03-ccss-1-7"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:3.3.1","ccss:3.4.1"],"prompt":"Salida: compara rutas e intercambio antes y hoy: un sacbe o canoa maya y una actividad productiva de Centroamerica conectada con Europa u otro continente.","type":"choice","props":{"options":[{"id":"a","text":"Hay continuidad al conectar intercambio; agricultura, industria o servicios actuales usan rutas de mayor alcance"},{"id":"b","text":"Las culturas antiguas comerciaban por avion con Europa"},{"id":"c","text":"Centroamerica actual no intercambia productos con otros continentes"}],"correct":["a"]},"id":"s03-ccss-1-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:3.3.1","ccss:3.4.1"],"prompt":"Salida nueva: compara la continuidad de rutas mayas e incas con conexiones actuales de actividades productivas centroamericanas hacia America del Norte, Europa y Asia.","type":"true-false","props":{"statements":[{"text":"Caminos, canoas y mensajeros antiguos apoyaron comunicacion e intercambio.","answer":true},{"text":"Agricultura, industria y servicios de Centroamerica pueden conectarse con otros continentes mediante rutas actuales.","answer":true},{"text":"Comparar antes y hoy implica afirmar que medios y escala no cambiaron.","answer":false}]},"id":"s03-ccss-1-9"}],"kind":"materia","area":"ccss","day":1}},{"missionId":"s03","version":"cnb-sexto-505c1a39634c4e43","lesson":{"id":"s03-ccss-2","title":"Actividades y condiciones de trabajo","icon":"BriefcaseBusiness","minutes":14,"gancho":"Dos personas pueden trabajar en comercio y tener condiciones laborales muy distintas.","objetivos":["Analizar actividades y condiciones de trabajo en Guatemala mediante los rasgos de la economia informal"],"resumen":["En Guatemala hay trabajo en agricultura, industria, construccion, comercio y servicios.","Las condiciones incluyen horario, seguridad, ingreso, contrato y prestaciones; varian incluso dentro de una misma actividad.","La economia informal suele operar sin registro o contrato laboral, con ingresos variables y sin prestaciones.","Informal no significa necesariamente ilegal ni deshonesto; describe condiciones economicas y laborales."],"media":{"id":"s03-ccss-2-trabajo","kind":"diagram","title":"Actividad y condicion laboral","aspect":"16:9","alt":"Cuatro escenas muestran agricultura, fabrica, construccion y venta, junto a criterios de contrato, seguridad, ingreso y prestaciones.","brief":"Diagrama 1600x900 ambientado en Guatemala con cuatro escenas respetuosas: trabajo agricola, fabrica, construccion y venta de mercado. Debajo, tabla de condiciones: contrato, registro, seguridad, ingreso y prestaciones. Aclarar que una imagen no basta para determinar formalidad. Texto grande, alto contraste e iconos ademas de color."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:4.1.1","ccss:4.1.5"],"prompt":"Analiza actividades y condiciones de trabajo en Guatemala y distingue rasgos de la economia informal.","type":"explain","props":{"icon":"BriefcaseBusiness","body":"Agricultura, fabrica, construccion, comercio y servicios son **actividades**. Contrato, registro, seguridad, salario o ingreso y prestaciones son **condiciones**. En la economia informal suelen faltar registro, contrato y prestaciones, y el ingreso puede variar; informal no significa necesariamente ilegal."},"id":"s03-ccss-2-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:4.1.1","ccss:4.1.5"],"title":"Dos preguntas diferentes","prompt":"Distingue que trabajo se realiza y bajo que condiciones se realiza en Guatemala.","type":"explain","props":{"icon":"ListChecks","body":"**Actividad:** cultivar maiz, coser ropa, construir, vender o transportar. **Condiciones:** horario, riesgos, pago, contrato y prestaciones. Un puesto registrado puede ofrecer contrato y prestaciones; una venta informal puede no tener registro, contrato ni ingreso estable. Se analiza evidencia, no la apariencia de la persona."},"id":"s03-ccss-2-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:4.1.1","ccss:4.1.5"],"title":"Modelo con evidencia suministrada","prompt":"Observa como analizar actividad, condiciones y economia informal sin juzgar a quien trabaja.","type":"worked-example","props":{"icon":"Store","problem":"Caso ficticio: Elena vende fruta en Guatemala. Compra su mercaderia, no tiene contrato ni prestaciones y sus ingresos cambian cada dia.","steps":[{"text":"Actividad: comercio."},{"text":"Condiciones: trabajo por cuenta propia, sin contrato ni prestaciones, con ingreso variable."},{"text":"Rasgos: corresponden a economia informal."},{"text":"Limite: informal no prueba ilegalidad ni falta de honradez."}],"answer":"La clasificacion usa condiciones suministradas, no prejuicios."},"id":"s03-ccss-2-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:4.1.1","ccss:4.1.5"],"prompt":"Con ayuda, clasifica datos de trabajo en Guatemala como actividad o condicion.","hint":"Pregunta si dice que se hace o como se trabaja.","explain":"Una actividad puede presentarse bajo condiciones distintas.","type":"sort","props":{"buckets":[{"id":"a","label":"Actividad","icon":"Hammer"},{"id":"c","label":"Condicion","icon":"ClipboardCheck"}],"items":[{"id":"1","text":"Cultivar hortalizas","bucket":"a"},{"id":"2","text":"Tener contrato escrito","bucket":"c"},{"id":"3","text":"Vender en el mercado","bucket":"a"},{"id":"4","text":"Recibir prestaciones","bucket":"c"}]},"id":"s03-ccss-2-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:4.1.1","ccss:4.1.5"],"prompt":"Un albanil trabaja por proyectos, sin contrato ni prestaciones y con ingreso variable. ¿Que analisis esta respaldado?","hint":"Usa solo las condiciones descritas.","explain":"El caso presenta rasgos frecuentes de economia informal; no demuestra ilegalidad.","type":"choice","props":{"options":[{"id":"a","text":"Construccion con rasgos informales por contrato, prestaciones e ingreso"},{"id":"b","text":"Trabajo ilegal porque no tiene salario fijo"},{"id":"c","text":"Agricultura formal porque usa herramientas"}],"correct":["a"]},"id":"s03-ccss-2-5"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:4.1.1","ccss:4.1.5"],"prompt":"Analiza este caso ficticio de Guatemala: Tomas presta servicio de reparacion, trabaja sin registro ni contrato, no recibe prestaciones y su ingreso varia. Identifica actividad, condiciones y rasgos de economia informal; aclara por que informal no significa ilegal.","type":"short-answer","props":{"minWords":24,"placeholder":"Actividad... Condiciones... Economia informal... Limite...","model":"La actividad es un servicio de reparacion. La falta de registro, contrato y prestaciones, junto con ingreso variable, son rasgos informales; no prueban ilegalidad.","rubric":["Identifique la actividad","Use cuatro condiciones","Evite estigmatizar"]},"id":"s03-ccss-2-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:4.1.1","ccss:4.1.5"],"prompt":"Compara dos trabajos en Guatemala: una trabajadora agricola con contrato, salario y prestaciones; y una venta de comida sin registro ni contrato, sin prestaciones y con ingreso variable. ¿Que analisis distingue actividad, condiciones y economia informal?","type":"choice","props":{"options":[{"id":"a","text":"Agricultura con condiciones formales; comercio con rasgos informales, sin que informal signifique ilegal"},{"id":"b","text":"Ambas actividades son informales porque venden productos"},{"id":"c","text":"Tener prestaciones convierte la agricultura en un servicio"}],"correct":["a"]},"id":"s03-ccss-2-7"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:4.1.1","ccss:4.1.5"],"prompt":"Salida: analiza en Guatemala una venta sin registro ni contrato, sin prestaciones y con ingreso variable; compara actividad y condiciones de economia informal.","type":"choice","props":{"options":[{"id":"a","text":"Actividad comercial con rasgos informales; estos no prueban que el trabajo sea ilegal"},{"id":"b","text":"Actividad agricola formal porque hay productos"},{"id":"c","text":"Las condiciones no pueden analizarse"}],"correct":["a"]},"id":"s03-ccss-2-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:4.1.1","ccss:4.1.5"],"prompt":"Salida nueva: distingue actividades y condiciones de trabajo en Guatemala y analiza contrato, registro, prestaciones e ingreso en la economia informal.","type":"true-false","props":{"statements":[{"text":"Agricultura, fabrica, construccion, comercio y servicios son actividades laborales.","answer":true},{"text":"Falta de contrato, registro y prestaciones e ingreso variable son rasgos frecuentes del trabajo informal.","answer":true},{"text":"Economia informal significa siempre actividad ilegal.","answer":false}]},"id":"s03-ccss-2-9"}],"kind":"materia","area":"ccss","day":3}},{"missionId":"s03","version":"cnb-sexto-d8f227c5a33441a6","lesson":{"id":"s03-pyd-1","title":"Círculos de calidad: resolver problemas en equipo","icon":"Users","minutes":15,"gancho":"En tu escuela el chorro se queda abierto y el agua se desperdicia. ¿Lo resuelve un cartel que diga \\"cierre el chorro\\", o hay que averiguar primero por qué pasa?","objetivos":["Analizar un problema cercano en un círculo de calidad mediante causas, efectos y PNI"],"resumen":["Un círculo de calidad es un grupo pequeño (de 4 a 8 personas) que se reúne con frecuencia, de forma voluntaria, para identificar un problema, analizar sus causas, proponer soluciones, aplicarlas y evaluarlas.","Roles: quien coordina (dirige la reunión), quien hace de secretaría (anota) y los participantes (todos opinan). Reglas: respeto, turnos para hablar y decisiones con datos.","Árbol de problemas: las raíces son las causas, el tronco es el problema y las ramas son los efectos. Se resuelve atacando las causas.","PNI: se anota lo Positivo, lo Negativo y lo Interesante de una propuesta antes de decidir."],"media":{"id":"s03-pyd-1-circulo","kind":"image","title":"Un círculo de calidad en acción","aspect":"16:9","alt":"Seis estudiantes sentados en círculo alrededor de un papelógrafo con un árbol dibujado: raíces con causas, tronco con el problema y ramas con efectos.","brief":"Ilustración de seis estudiantes de sexto (niñas y niños diversos) sentados en círculo en el corredor de una escuela. En el centro, un papelógrafo con un árbol dibujado a marcador: en las raíces tarjetas amarillas (\\"chorro flojo\\", \\"nadie revisa\\"), en el tronco \\"Se desperdicia el agua\\", en las ramas tarjetas celestes (\\"baño sucio\\", \\"tanque vacío\\"). Una niña coordina con un marcador, un niño anota en un cuaderno (secretaría). Al fondo, el chorro de la pila. Estilo plano, colores cálidos, sin textos adicionales. Dimensiones: 1600x900."},"steps":[{"fase":"explorar","areas":["pyd"],"cnb":["pyd:2.3.2"],"ambito":"conocer","title":"¿Qué es un círculo de calidad?","prompt":"Un **círculo de calidad** es un grupo pequeño que se reúne para **mejorar algo** de su entorno. Toca cada tarjeta.","type":"explain","props":{"icon":"Users","body":"Se llama \\"de calidad\\" porque busca que las cosas **funcionen mejor**, y \\"círculo\\" porque todos se sientan como iguales y todos opinan.","reveal":[{"icon":"Users","front":"¿Quiénes lo forman?","back":"De **4 a 8 personas** que comparten el mismo espacio (un grado, un comité, un taller). Participan **de forma voluntaria**."},{"icon":"Calendar","front":"¿Cómo trabajan?","back":"Se reúnen **con frecuencia** (por ejemplo, cada semana) y siguen pasos: problema → datos → causas → soluciones → aplicar → evaluar."},{"icon":"ClipboardList","front":"Roles","back":"**Coordinación:** dirige la reunión y da la palabra. **Secretaría:** anota ideas y acuerdos. **Participantes:** aportan ideas y datos."},{"icon":"Scale","front":"Reglas","back":"Respeto, **turnos** para hablar, criticar ideas y no personas, y decidir con **datos**, no con suposiciones."}]},"id":"s03-pyd-1-1"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.3.1"],"ambito":"emprender","prompt":"El chorro de la escuela se queda abierto y el agua se desperdicia. ¿Qué conviene hacer **primero**?","explain":"Antes de proponer, hay que **averiguar las causas**: quizá el chorro está flojo, quizá nadie revisa o quizá los pequeños no alcanzan a cerrarlo. Cada causa tiene una solución distinta.","type":"choice","props":{"options":[{"id":"a","text":"Averiguar por qué se queda abierto","icon":"Search"},{"id":"b","text":"Castigar a quien lo dejó abierto","icon":"Gavel","feedback":"Sin saber la causa, podrías castigar a alguien que no tuvo la culpa y el problema seguiría."},{"id":"c","text":"Poner un cartel y ya","icon":"FileText","feedback":"Un cartel puede ayudar, pero si la causa es que el chorro está dañado, no servirá."}],"correct":["a"]},"id":"s03-pyd-1-2"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.3.2"],"prompt":"Ordena los **pasos** que sigue un círculo de calidad.","hint":"No se pueden buscar causas sin datos, ni evaluar algo que aún no se ha aplicado.","explain":"Identificar el problema → reunir datos → analizar causas → proponer y elegir soluciones → aplicar → evaluar.","type":"order","props":{"labels":{"start":"Primero","end":"Al final"},"items":[{"id":"c1","text":"Identificar el problema","icon":"Target"},{"id":"c2","text":"Reunir datos (observar, contar, preguntar)","icon":"ClipboardList"},{"id":"c3","text":"Analizar las causas","icon":"Search"},{"id":"c4","text":"Proponer y elegir soluciones","icon":"Lightbulb"},{"id":"c5","text":"Aplicar la solución","icon":"Hammer"},{"id":"c6","text":"Evaluar si funcionó","icon":"ClipboardCheck"}]},"id":"s03-pyd-1-3"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.3.1"],"ambito":"conocer","title":"Técnica 1: el árbol de problemas","prompt":"Para separar **causas** y **efectos** se dibuja un **árbol**. Toca cada parte.","type":"explain","props":{"icon":"TreeDeciduous","body":"Si solo cortas las ramas (efectos), el árbol vuelve a crecer. Para resolver un problema hay que atender sus **raíces** (causas).","reveal":[{"icon":"Sprout","front":"Raíces = causas","back":"¿**Por qué** pasa? Ejemplo: no hay basureros; la refacción viene en bolsas plásticas."},{"icon":"TreePine","front":"Tronco = problema","back":"Lo que queremos resolver, en una oración: \\"Hay basura en el patio\\"."},{"icon":"Leaf","front":"Ramas = efectos","back":"¿**Qué provoca**? Ejemplo: moscas, mal olor, drenajes tapados cuando llueve."}]},"id":"s03-pyd-1-4"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.3.1"],"prompt":"Problema: **\\"Hay basura en el patio de la escuela\\"**. ¿Cada tarjeta es una **causa** (raíz) o un **efecto** (rama)?","hint":"Causa = por qué pasa (viene antes). Efecto = qué provoca (viene después).","explain":"Las causas explican por qué hay basura; los efectos son lo que la basura provoca. Las soluciones deben atacar las causas.","type":"sort","props":{"buckets":[{"id":"cau","label":"Causa (raíz)","icon":"Sprout","color":"var(--c-maiz-strong)"},{"id":"efe","label":"Efecto (rama)","icon":"Leaf","color":"var(--area-pyd)"}],"items":[{"id":"b1","text":"Solo hay un basurero para toda la escuela","bucket":"cau"},{"id":"b2","text":"Hay moscas cerca de la tienda escolar","bucket":"efe"},{"id":"b3","text":"La refacción se vende en bolsas plásticas","bucket":"cau"},{"id":"b4","text":"Los drenajes se tapan cuando llueve","bucket":"efe"},{"id":"b5","text":"Nadie tiene turno para recoger la basura","bucket":"cau"},{"id":"b6","text":"El patio huele mal","bucket":"efe"}]},"id":"s03-pyd-1-5"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.3.1"],"ambito":"conocer","title":"Técnica 2: el análisis PNI","prompt":"Cuando hay una **propuesta** de solución, antes de decidir se analiza con **PNI**. Toca cada letra.","type":"explain","props":{"icon":"ListChecks","body":"El PNI evita decir \\"¡sí!\\" o \\"¡no!\\" demasiado rápido. Obliga a mirar la propuesta **por todos lados**.","reveal":[{"icon":"ThumbsUp","front":"P = Positivo","back":"¿Qué tiene de **bueno** la propuesta? ¿A quién beneficia?"},{"icon":"X","front":"N = Negativo","back":"¿Qué **problemas o riesgos** trae? ¿A quién podría afectar?"},{"icon":"Lightbulb","front":"I = Interesante","back":"¿Qué **preguntas o ideas nuevas** despierta? Lo que no es ni bueno ni malo, pero vale la pena investigar."}]},"id":"s03-pyd-1-6"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.3.1","pyd:2.3.2"],"ambito":"hacer","title":"Ejemplo resuelto: un PNI en el círculo de calidad","prompt":"El círculo de calidad de sexto analiza una propuesta de la comunidad. Mira cómo hace su PNI.","type":"worked-example","props":{"icon":"ClipboardList","problem":"Propuesta: **\\"Cerrar la calle del mercado a los carros los domingos para que la gente camine segura.\\"**","steps":[{"text":"**P (positivo):** menos accidentes; las familias caminan tranquilas; más espacio para los puestos."},{"text":"**N (negativo):** los que traen carga en pick-up tendrán que descargar más lejos; puede haber tráfico en otras calles."},{"text":"**I (interesante):** ¿cuántos accidentes hubo el año pasado? ¿Dónde podrían estacionarse los pick-ups? ¿Venderán más los comerciantes?","why":"Lo interesante se convierte en preguntas para reunir más datos."},{"text":"**Decisión del círculo:** apoyar la propuesta, pero con un **lugar de descarga** cerca para los comerciantes."}],"answer":"Con el PNI, el círculo **mejoró** la propuesta: mantuvo lo positivo y buscó cómo reducir lo negativo.","tip":"Positivo → Negativo → Interesante → decidir (y mejorar la propuesta)."},"id":"s03-pyd-1-7"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:2.3.1"],"ambito":"hacer","prompt":"Ahora tú. Propuesta: **\\"Que sexto grado administre una tienda de refacción saludable en la escuela.\\"** Clasifica cada idea en P, N o I.","explain":"P: lo bueno (alimentación sana, ganancias). N: los riesgos (tiempo, dinero). I: preguntas nuevas para investigar.","type":"sort","props":{"buckets":[{"id":"p","label":"P · Positivo","icon":"ThumbsUp","color":"var(--c-ok)"},{"id":"n","label":"N · Negativo","icon":"X","color":"var(--c-bad)"},{"id":"i","label":"I · Interesante","icon":"Lightbulb","color":"var(--c-maiz-strong)"}],"items":[{"id":"r1","text":"Los estudiantes comerían más fruta y menos golosinas","bucket":"p"},{"id":"r2","text":"Atender la tienda podría quitar tiempo del recreo a los encargados","bucket":"n"},{"id":"r3","text":"¿Qué frutas de temporada serían más baratas cada mes?","bucket":"i"},{"id":"r4","text":"Las ganancias podrían usarse para la excursión del grado","bucket":"p"},{"id":"r5","text":"Si no se vende la fruta, se puede echar a perder","bucket":"n"},{"id":"r6","text":"¿Podrían las familias de la aldea vender sus frutas a la tienda?","bucket":"i"}]},"id":"s03-pyd-1-8"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:2.3.1"],"ambito":"emprender","prompt":"Análisis de caso: el círculo de calidad descubrió que el chorro de la escuela se queda abierto porque **la llave está floja y no cierra bien**. ¿Qué solución ataca **la causa**?","explain":"La causa es una llave dañada: la solución que ataca la raíz es **repararla o cambiarla**. Los carteles o regaños no arreglan una llave floja.","type":"choice","props":{"options":[{"id":"a","text":"Pedir a la dirección y a un padre de familia que cambien la llave del chorro"},{"id":"b","text":"Regañar a todos los estudiantes en la formación","feedback":"Los estudiantes no tienen la culpa de que la llave esté floja."},{"id":"c","text":"Poner un cartel más grande","feedback":"Aunque todos quieran cerrarlo, la llave dañada no cierra bien."}],"correct":["a"]},"id":"s03-pyd-1-9"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:2.3.2"],"prompt":"¿Qué es un **círculo de calidad**?","type":"choice","props":{"options":[{"id":"a","text":"Un grupo pequeño que se reúne con frecuencia para analizar problemas y proponer soluciones"},{"id":"b","text":"Un juego de pelota en círculo"},{"id":"c","text":"Una tienda que vende productos caros"}],"correct":["a"]},"id":"s03-pyd-1-10"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:2.3.1","pyd:2.3.2"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"En un análisis PNI, la I significa \\"Interesante\\".","answer":true},{"text":"En el árbol de problemas, las raíces representan los efectos.","answer":false,"why":"Las raíces son las causas; las ramas son los efectos."},{"text":"En un círculo de calidad, la secretaría anota las ideas y los acuerdos.","answer":true},{"text":"Un círculo de calidad debe tener al menos 30 personas.","answer":false,"why":"Es un grupo pequeño, de 4 a 8 personas."}]},"id":"s03-pyd-1-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["pyd"],"cnb":["pyd:2.3.1","pyd:2.3.2"],"type":"reflection","props":{"statements":["Explico qué es un círculo de calidad y sus pasos","Separo causas y efectos con el árbol de problemas","Evalúo una propuesta con PNI"],"commitments":["Propondré formar un círculo de calidad en mi grado","Antes de decir sí o no a una idea, haré su PNI"]},"id":"s03-pyd-1-12"}],"kind":"materia","area":"pyd","day":3}},{"missionId":"s03","version":"cnb-sexto-1cf074a0792a47d8","lesson":{"id":"s03-ccss-3","title":"Roles de las mujeres: cambios y continuidades","icon":"Users","minutes":14,"gancho":"Las responsabilidades y oportunidades de las mujeres han variado entre sociedades y epocas.","objetivos":["Comparar roles de las mujeres en distintas culturas y epocas en los ambitos familiar, economico y politico"],"resumen":["Los roles de las mujeres no han sido iguales en todas las culturas, epocas ni grupos sociales.","El ambito familiar incluye cuidado y decisiones del hogar; el economico, produccion, comercio y trabajo remunerado; el politico, autoridad y participacion publica.","Las fuentes muestran tanto continuidades como cambios, pero un ejemplo no representa a todas las mujeres."],"media":{"id":"s03-ccss-3-mujeres","kind":"diagram","title":"Roles en tres ambitos","aspect":"16:9","alt":"Una tabla compara roles familiares, economicos y politicos de mujeres en distintas culturas y epocas.","brief":"Diagrama comparativo 1600x900 con tres columnas: familiar, economico y politico. Filas con ejemplos historicos contextualizados y actuales: administracion de hogar, produccion y comercio, autoridad o participacion publica. Incluir nota: los roles variaron segun cultura, epoca y condicion social. Representacion diversa, no estereotipada, texto grande y alto contraste."},"steps":[{"fase":"explorar","areas":["ccss"],"cnb":["ccss:4.2.2"],"prompt":"Compara roles de las mujeres entre culturas y epocas en los ambitos familiar, economico y politico, reconociendo cambios y continuidades.","type":"explain","props":{"icon":"Users","body":"En distintas sociedades, las mujeres han cuidado familias, producido alimentos, comerciado, trabajado y participado en decisiones. Las posibilidades cambiaron segun cultura, epoca y condicion social; ningun ejemplo describe a todas."},"id":"s03-ccss-3-1"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:4.2.2"],"title":"Tres ambitos para comparar","prompt":"Distingue roles familiares, economicos y politicos de las mujeres a traves del tiempo.","type":"explain","props":{"icon":"Columns3","body":"**Familiar:** cuidado, administracion y decisiones del hogar. **Economico:** agricultura, artesania, comercio, profesiones y trabajo remunerado. **Politico:** autoridad, organizacion y participacion publica. Comparar busca cambios y continuidades, no ordenar culturas como superiores."},"id":"s03-ccss-3-2"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:4.2.2"],"title":"Modelo con dos fichas","prompt":"Observa una comparacion entre mujeres de culturas y epocas distintas en los tres ambitos.","type":"worked-example","props":{"icon":"GitCompare","problem":"Ficha A: una comerciante maya participaba en produccion y mercado, cuidaba a su familia y podia influir en redes locales. Ficha B: una alcaldesa guatemalteca actual combina trabajo remunerado, responsabilidades familiares compartidas y autoridad politica.","steps":[{"text":"Familiar: ambas participan, pero hoy puede destacarse responsabilidad compartida."},{"text":"Economico: ambas realizan trabajo productivo o comercial."},{"text":"Politico: cambia el acceso formal a un cargo electo."},{"text":"Limite: dos fichas no representan a todas las mujeres."}],"answer":"Hay continuidad economica y cambios en formas de participacion politica y familiar."},"id":"s03-ccss-3-3"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:4.2.2"],"prompt":"Con ayuda, organiza ejemplos de roles de mujeres de distintas culturas y epocas por ambito.","hint":"Pregunta si corresponde al hogar, la produccion e intercambio o la decision publica.","explain":"Un mismo rol puede relacionarse con mas de un ambito; aqui se usa su funcion principal en la ficha.","type":"sort","props":{"buckets":[{"id":"f","label":"Familiar","icon":"House"},{"id":"e","label":"Economico","icon":"Store"},{"id":"p","label":"Politico","icon":"Landmark"}],"items":[{"id":"1","text":"Administrar alimentos del hogar","bucket":"f"},{"id":"2","text":"Vender textiles en un mercado","bucket":"e"},{"id":"3","text":"Participar en un consejo comunitario","bucket":"p"}]},"id":"s03-ccss-3-4"},{"fase":"construir","areas":["ccss"],"cnb":["ccss:4.2.2"],"prompt":"Al comparar roles de mujeres entre culturas y epocas, ¿que conclusion es cuidadosa?","hint":"Evita convertir un ejemplo en regla universal.","explain":"Las fuentes permiten observar cambios y continuidades, con diferencias por cultura y condicion social.","type":"choice","props":{"options":[{"id":"a","text":"Los roles familiares, economicos y politicos variaron y no fueron iguales para todas"},{"id":"b","text":"Todas las mujeres de una epoca tuvieron la misma vida"},{"id":"c","text":"Las mujeres nunca participaron en actividades economicas"}],"correct":["a"]},"id":"s03-ccss-3-5"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:4.2.2"],"prompt":"Compara de forma independiente los roles de mujeres de estas dos fichas: una artesana de una cultura antigua produce ceramica, administra alimentos familiares y no ocupa el consejo; una cooperativista actual comparte cuidados, vende productos y representa a su grupo ante el municipio. Explica cambio y continuidad familiar, economica y politica, sin generalizar.","type":"short-answer","props":{"minWords":27,"placeholder":"Familiar... Economico... Politico... Cambio y continuidad...","model":"Ambas participan en familia y produccion. La cooperativista comparte cuidados y tiene representacion politica formal. Es un contraste cuidadoso entre las dos fichas suministradas, no entre todas las mujeres.","rubric":["Compare los tres ambitos","Explique cambio y continuidad","Evite generalizaciones"]},"id":"s03-ccss-3-6"},{"fase":"aplicar","areas":["ccss"],"cnb":["ccss:4.2.2"],"prompt":"Una fuente historica muestra agricultoras y comerciantes; una actual muestra mujeres en cargos publicos y trabajos diversos. ¿Que comparacion es valida?","type":"choice","props":{"options":[{"id":"a","text":"Hay continuidad economica y cambios en oportunidades politicas, con variaciones entre culturas y personas"},{"id":"b","text":"La fuente prueba que todas tuvieron los mismos roles familiares"},{"id":"c","text":"Solo el presente tiene trabajo realizado por mujeres"}],"correct":["a"]},"id":"s03-ccss-3-7"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:4.2.2"],"prompt":"Salida: compara roles de mujeres de distintas culturas y epocas en familia, economia y politica mediante cambios y continuidades.","type":"choice","props":{"options":[{"id":"a","text":"El trabajo familiar y economico muestra continuidades; la participacion politica presenta cambios, sin representar igual a todas"},{"id":"b","text":"Una sola ficha demuestra que todas las culturas asignaron roles identicos"},{"id":"c","text":"Los roles economicos nunca se relacionaron con mujeres"}],"correct":["a"]},"id":"s03-ccss-3-8"},{"fase":"comprobar","areas":["ccss"],"cnb":["ccss:4.2.2"],"prompt":"Salida nueva: compara cambios y continuidades de roles de las mujeres entre culturas y tiempos en los ambitos familiar, economico y politico.","type":"true-false","props":{"statements":[{"text":"Las mujeres han participado en actividades familiares y economicas en distintas sociedades.","answer":true},{"text":"Las oportunidades de participacion politica han variado entre culturas y epocas.","answer":true},{"text":"Un ejemplo permite generalizar la misma experiencia a todas las mujeres.","answer":false}]},"id":"s03-ccss-3-9"}],"kind":"materia","area":"ccss","day":4}},{"missionId":"s03","version":"cnb-sexto-4c8727d168b186ec","lesson":{"id":"s03-art-2","title":"Técnica mixta para un cartel que comunica","icon":"Megaphone","minutes":15,"gancho":"Caminando por tu comunidad ves carteles de ferias, campañas de vacunación y rutas de evacuación. ¿Por qué algunos se entienden en un segundo y otros no?","objetivos":["Diseñar un cartel público claro mediante técnica mixta, ícono, contraste y pocas palabras"],"resumen":["Tintas: tinta china, marcadores y acuarelas. Dan líneas firmes (tinta) o manchas transparentes (acuarela).","Técnica mixta: combinar dos o más técnicas en una obra. La más conocida es crayón + acuarela: la cera rechaza el agua y los trazos de crayón resaltan.","Un ícono es un dibujo sencillo que se entiende sin palabras (una gota = agua, un corazón = salud o amor).","Un buen cartel tiene un mensaje principal, un ícono grande, colores con contraste, pocas palabras con letras grandes y espacio libre para respirar."],"media":{"id":"s03-art-2-carteles","kind":"image","title":"¿Cuál se entiende mejor?","aspect":"4:3","alt":"Dos carteles sobre cuidar el agua. El primero tiene mucho texto pequeño y dibujos diminutos. El segundo tiene una gota grande, el título \\"Cierra el chorro\\" y colores azul y amarillo que contrastan.","brief":"Ilustración escolar de dos carteles verticales colgados en una pared de escuela pública guatemalteca. Cartel A (mal ejemplo): fondo celeste pálido, 6 renglones de texto pequeño, 5 dibujos diminutos, letras claras sobre fondo claro. Cartel B (buen ejemplo): fondo amarillo, gota azul enorme con una llave de chorro cerrada, título en letras grandes \\"Cierra el chorro\\", una línea pequeña \\"Cada gota cuenta\\", espacio libre alrededor. Técnica visible: crayón de cera con acuarela. Sin marcas ni logotipos. Dimensiones: 1200x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["art"],"cnb":["art:2.2.1"],"ambito":"conocer","title":"Tintas y técnica mixta","prompt":"Además de las técnicas secas, hay técnicas con **tinta** y con **agua**. Y se pueden **combinar**. Toca cada tarjeta.","type":"explain","props":{"icon":"PenTool","body":"Cuando una obra usa **dos o más técnicas**, decimos que es de **técnica mixta**.","reveal":[{"icon":"PenTool","front":"Tinta","back":"La **tinta china** o los **marcadores** dan líneas firmes y oscuras. Sirven para contornos y letras. Déjala secar antes de tocarla para no manchar."},{"icon":"Droplet","front":"Acuarela","back":"Pintura que se diluye en **agua**. Da manchas **transparentes** y suaves. Se usa con pincel y poca agua para no romper el papel."},{"icon":"Layers","front":"Crayón + acuarela","back":"Dibuja con crayón de cera y luego pinta encima con acuarela: la **cera rechaza el agua** y tus trazos quedan brillando. Se llama técnica de **reserva**."},{"icon":"Scissors","front":"Otras mezclas","back":"**Collage** (papeles recortados) con lápiz de color; tinta con crayón; pastel sobre acuarela seca. ¡Experimenta!"}]},"id":"s03-art-2-1"},{"fase":"construir","areas":["art"],"cnb":["art:2.2.1"],"ambito":"conocer","prompt":"Observa los dos carteles. Si pasas en bicicleta frente a ellos, ¿cuál entenderías **en un segundo**?","explain":"El cartel B usa un **ícono grande**, **pocas palabras** y **colores que contrastan**. Hoy aprenderás a diseñar así, usando técnicas gráficas.","type":"choice","props":{"options":[{"id":"a","text":"El cartel A, porque explica más cosas","icon":"FileText","feedback":"Tiene mucha información, pero nadie la lee de pasada. Un cartel debe entenderse rápido."},{"id":"b","text":"El cartel B, porque su mensaje se ve de lejos","icon":"Eye"}],"correct":["b"]},"id":"s03-art-2-2"},{"fase":"construir","areas":["art"],"cnb":["art:2.2.1"],"ambito":"conocer","title":"El lenguaje de los íconos en un cartel","prompt":"Un **cartel** o **afiche** es una imagen que comunica **un mensaje rápido** a mucha gente. Su herramienta principal es el **ícono**.","media":{"id":"s03-art-2-iconos","kind":"diagram","title":"Íconos que hablan","aspect":"16:9","alt":"Seis íconos sencillos en recuadros: una gota, una mano con agua, un árbol, una flecha de salida, un corazón y un bote de basura, cada uno con la palabra que representa.","brief":"Diagrama de 6 íconos planos de trazo grueso (estilo señalética), en cuadrícula 3×2 sobre fondo blanco: gota (agua), manos con gotas (lavado de manos), árbol (bosque), flecha verde saliendo por una puerta (salida), corazón (salud), bote con flecha (basura en su lugar). Debajo, la palabra. A la derecha, un ejemplo de cartel que usa uno de ellos en grande. Colores planos con contraste alto. Dimensiones: 1600x900."},"type":"explain","props":{"icon":"Megaphone","body":"Los diseñadores siguen **cinco reglas** para que un cartel funcione. Toca cada una.","reveal":[{"icon":"Target","front":"1. Un solo mensaje","back":"¿Qué quieres que la gente haga o sepa? Dilo en **una frase corta**: \\"Cierra el chorro\\"."},{"icon":"Image","front":"2. Un ícono grande","back":"Un dibujo **sencillo** que se entiende sin leer. Mejor uno grande que muchos pequeños."},{"icon":"Contrast","front":"3. Contraste","back":"Colores que se distinguen bien: oscuro sobre claro (azul sobre amarillo, negro sobre blanco). Claro sobre claro no se lee."},{"icon":"Type","front":"4. Pocas palabras, letras grandes","back":"El título debe leerse **a varios pasos de distancia**. Lo más importante, más grande."},{"icon":"Maximize2","front":"5. Espacio libre","back":"Deja zonas vacías alrededor del ícono y del título: el ojo descansa y encuentra rápido el mensaje."}]},"id":"s03-art-2-3"},{"fase":"construir","areas":["art"],"cnb":["art:2.2.1"],"ambito":"hacer","title":"Ejemplo resuelto: el cartel de lavado de manos","prompt":"Mira cómo Kevin planifica un cartel para el lavamanos de su escuela.","type":"worked-example","props":{"icon":"Hand","problem":"La escuela necesita un cartel para recordar lavarse las manos antes de la refacción. Kevin tiene crayones, acuarelas y un marcador negro.","steps":[{"text":"**Mensaje:** \\"Lávate las manos\\" (una sola idea)."},{"text":"**Ícono:** dos manos con gotas de agua y burbujas, grande, en el centro.","why":"Se entiende aunque alguien no lea bien o hable otro idioma."},{"text":"**Técnica mixta:** dibuja las burbujas con crayón **blanco** y luego pinta todo el fondo con acuarela **azul**: las burbujas aparecen brillando.","why":"La cera rechaza el agua (técnica de reserva)."},{"text":"**Letras:** cuando la acuarela seca, escribe el título con marcador negro, en letras grandes, arriba.","why":"Negro sobre azul claro da buen contraste; esperar el secado evita manchas."},{"text":"**Revisión:** se aleja cinco pasos. ¿Se entiende? Deja espacio libre alrededor de las manos."}],"answer":"Un cartel con **un mensaje**, **un ícono grande**, **contraste**, **pocas palabras** y **técnica mixta** (crayón + acuarela + tinta).","tip":"Haz primero un boceto pequeño a lápiz; así corriges antes de usar los materiales."},"id":"s03-art-2-4"},{"fase":"construir","areas":["art"],"cnb":["art:2.2.1"],"ambito":"conocer","prompt":"Revisa lo aprendido. ¿Verdadero o falso?","hint":"Piensa en las cinco reglas del cartel y en por qué funciona la técnica crayón + acuarela.","explain":"La cera reserva el dibujo, mientras el ícono grande, el contraste y pocas palabras hacen legible el mensaje público.","type":"true-false","props":{"statements":[{"text":"En la técnica de reserva, la cera del crayón rechaza la acuarela.","answer":true},{"text":"Un cartel es mejor si tiene muchos dibujos pequeños.","answer":false,"why":"Se ve saturado. Es mejor un ícono grande y claro."},{"text":"Letras amarillas sobre fondo blanco tienen buen contraste.","answer":false,"why":"Claro sobre claro casi no se lee. Usa oscuro sobre claro."},{"text":"Una obra que combina tinta, crayón y acuarela es de técnica mixta.","answer":true}]},"id":"s03-art-2-5"},{"fase":"aplicar","areas":["art"],"cnb":["art:2.2.1"],"ambito":"hacer","prompt":"Tu grado hará un cartel para la **ruta de evacuación** en caso de sismo. ¿Qué diseño es el más adecuado?","explain":"Una flecha grande (ícono), pocas palabras (\\"Salida\\") y colores con mucho contraste (blanco sobre verde, como las señales de evacuación) se entienden rápido, incluso con prisa.","type":"choice","props":{"options":[{"id":"a","text":"Una flecha blanca grande sobre fondo verde con la palabra \\"SALIDA\\""},{"id":"b","text":"Un párrafo que explica qué hacer durante un sismo, en letra pequeña","feedback":"En una emergencia nadie lee un párrafo. El cartel debe entenderse de un vistazo."},{"id":"c","text":"Un paisaje con volcanes y muchas flechas pequeñas de colores","feedback":"Es bonito, pero confunde: ¿cuál flecha seguir?"}],"correct":["a"]},"id":"s03-art-2-6"},{"fase":"aplicar","areas":["art"],"cnb":["art:2.2.1"],"ambito":"hacer","prompt":"Planifica un **cartel** para tu escuela o comunidad (ruta segura, cuidado del agua, no tirar basura…). Describe tu plan: **mensaje**, **ícono**, **colores** (con contraste) y **técnica gráfica** que usarás y por qué.","type":"short-answer","props":{"minWords":35,"placeholder":"Mi mensaje será… El ícono… Los colores… Usaré la técnica… porque…","model":"Mi mensaje será \\"Basura en su lugar\\". El ícono será un bote de basura grande con una bolsa entrando. Usaré fondo amarillo y el bote en verde oscuro con contorno negro para que contraste. Haré técnica mixta: dibujaré el bote con crayones de cera y pintaré el fondo con acuarela amarilla, porque la cera no deja pasar el agua. El título lo escribiré con marcador negro en letras grandes.","rubric":["Tiene un solo mensaje corto","Describe un ícono grande y sencillo","Elige colores con contraste","Nombra la técnica gráfica y explica por qué la eligió"]},"id":"s03-art-2-7"},{"fase":"aplicar","areas":["art"],"cnb":["art:2.2.1"],"ambito":"hacer","prompt":"**En casa:** realiza tu cartel en tamaño carta o más grande y pruébalo con tu familia.","type":"project","props":{"goal":"Producir un cartel con técnica mixta que se entienda a cinco pasos de distancia.","steps":[{"title":"Boceto","detail":"En un papel pequeño, dibuja a lápiz dónde irán el ícono, el título y el espacio libre."},{"title":"Crayón primero","detail":"Dibuja el ícono y los detalles que quieras \\"reservar\\" con crayón de cera, apretando fuerte."},{"title":"Color y tinta","detail":"Pinta el fondo con acuarela (o crayón o lápices, si no tienes). Cuando seque, escribe el título con marcador o tinta."},{"title":"Prueba de los cinco pasos","detail":"Pega el cartel en la pared, aléjate cinco pasos y pregunta a alguien de tu familia qué dice. Si duda, mejora el contraste o agranda el ícono."}],"evidence":"Tu cartel terminado y una nota con lo que tu familia entendió al verlo.","rubric":["Mi cartel tiene un solo mensaje","El ícono es grande y claro","Usé al menos dos técnicas gráficas","Se entiende a cinco pasos"]},"id":"s03-art-2-8"},{"fase":"comprobar","areas":["art"],"cnb":["art:2.2.1"],"prompt":"¿Por qué funciona la técnica de dibujar con **crayón de cera** y pintar encima con **acuarela**?","type":"choice","props":{"options":[{"id":"a","text":"Porque la cera rechaza el agua y los trazos quedan visibles"},{"id":"b","text":"Porque la acuarela borra el crayón"},{"id":"c","text":"Porque el crayón se disuelve en el agua"}],"correct":["a"]},"id":"s03-art-2-9"},{"fase":"comprobar","areas":["art"],"cnb":["art:2.2.1"],"prompt":"Clasifica cada decisión de diseño: ¿ayuda o estorba a que el cartel se entienda?","type":"sort","props":{"buckets":[{"id":"si","label":"Ayuda","icon":"ThumbsUp","color":"var(--c-ok)"},{"id":"no","label":"Estorba","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"d1","text":"Un ícono grande y sencillo","bucket":"si"},{"id":"d2","text":"Título en letras pequeñas","bucket":"no"},{"id":"d3","text":"Letras oscuras sobre fondo claro","bucket":"si"},{"id":"d4","text":"Cinco mensajes distintos","bucket":"no"},{"id":"d5","text":"Espacio libre alrededor del ícono","bucket":"si"}]},"id":"s03-art-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["art"],"cnb":["art:2.2.1"],"type":"reflection","props":{"statements":["Uso presión, capas y degradado con técnicas secas","Explico cómo funciona la técnica mixta de crayón y acuarela","Diseño un cartel con un ícono, contraste y pocas palabras"],"commitments":["Completaré mi muestrario de técnicas","Haré mi cartel y lo probaré a cinco pasos","Observaré los carteles de mi comunidad y pensaré cómo mejorarlos"]},"id":"s03-art-2-11"}],"kind":"materia","area":"art","day":4}},{"missionId":"s03","version":"cnb-sexto-9bc04c4089b55c58","lesson":{"id":"s03-mat-5","title":"Caras congruentes en los cuerpos","icon":"Package","minutes":14,"gancho":"Si desarmas una caja de zapatos, ¿cuántas piezas iguales encuentras?","objetivos":["Identificar y justificar cuáles caras son congruentes en prismas, pirámides y cilindros"],"resumen":["Las dos bases de un prisma y de un cilindro siempre son congruentes.","En una caja (prisma rectangular) las caras opuestas son congruentes: hay 3 pares. En un cubo, las 6 caras son congruentes.","En una pirámide recta de base regular, con la cúspide sobre el centro, todas las caras laterales son triángulos congruentes.","En un prisma recto de base regular, las caras laterales son rectángulos congruentes.","El cono tiene una sola base: no tiene caras planas congruentes entre sí."],"media":{"id":"s03-mat-5-caja","kind":"animation","title":"Una caja que se desarma","aspect":"16:9","duration":35,"alt":"Una caja se abre y queda extendida en el plano; las caras congruentes se iluminan del mismo color de dos en dos.","brief":"Animación 2D de 35 s. Una caja de cartón sin marcas (30 × 20 × 10 cm) gira, se abre y queda desplegada sobre la mesa. Las caras se colorean por pares congruentes: las dos de 30 × 20 en azul, las dos de 30 × 10 en verde y las dos de 20 × 10 en amarillo, con sus medidas. Luego un cubo desplegado con sus 6 caras del mismo color. Narración: \\"caras congruentes: misma forma y mismo tamaño\\". Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["mat"],"cnb":["mat:1.3.2"],"ambito":"conocer","title":"Caras congruentes","prompt":"Dos caras son **congruentes** si tienen la misma forma y el mismo tamaño (encajarían una sobre otra). Toca cada cuerpo.","type":"explain","props":{"icon":"Copy","body":"Pista general: las **bases** de prismas y cilindros siempre son congruentes.","reveal":[{"icon":"Box","front":"Prisma rectangular","back":"Caras opuestas congruentes: **3 pares**."},{"icon":"Dice5","front":"Cubo","back":"Sus **6 caras** son cuadrados congruentes."},{"icon":"Cylinder","front":"Cilindro","back":"Sus **2 bases** son círculos congruentes."},{"icon":"Triangle","front":"Pirámide recta de base regular","back":"Si la **cúspide está sobre el centro** de la base, todas sus **caras laterales** son triángulos congruentes. Con base cuadrada: 4 triángulos iguales."}]},"id":"s03-mat-5-1"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.3.2"],"ambito":"conocer","prompt":"En una caja de zapatos, ¿qué caras son **iguales** en forma y tamaño?","explain":"Las caras **opuestas** (la de arriba y la de abajo, las de los lados, la de enfrente y la de atrás) son **congruentes**.","type":"choice","props":{"options":[{"id":"a","text":"Las caras opuestas","icon":"Copy"},{"id":"b","text":"Todas las caras","icon":"Layers","feedback":"Eso pasa en un cubo; en una caja de zapatos hay caras largas y caras cortas."},{"id":"c","text":"Ninguna","icon":"X","feedback":"Mira la tapa y el fondo: miden lo mismo."}],"correct":["a"]},"id":"s03-mat-5-2"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.3.2"],"ambito":"hacer","title":"Ejemplo resuelto","prompt":"Así se encuentran las caras congruentes de una caja con medidas.","type":"worked-example","props":{"icon":"Package","problem":"Una caja de cardamomo mide **30 cm de largo, 20 cm de ancho y 10 cm de alto**. ¿Qué caras son congruentes?","steps":[{"text":"Tapa y fondo: rectángulos de **30 × 20**. Son 2 caras congruentes."},{"text":"Frente y atrás: rectángulos de **30 × 10**. Otras 2 congruentes."},{"text":"Lados izquierdo y derecho: rectángulos de **20 × 10**. Otras 2 congruentes.","why":"Cada cara usa dos de las tres medidas de la caja."}],"answer":"Hay **3 pares** de caras congruentes: 30 × 20, 30 × 10 y 20 × 10.","tip":"Las caras opuestas de un prisma rectangular siempre son congruentes."},"id":"s03-mat-5-3"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.3.2"],"prompt":"¿Son congruentes estas caras?","hint":"Congruentes = misma forma y mismo tamaño.","explain":"Las bases de prismas y cilindros son congruentes. En una pirámide recta de base regular, con la cúspide sobre el centro, también son congruentes sus caras laterales.","type":"sort","props":{"buckets":[{"id":"si","label":"Congruentes","icon":"Check","color":"var(--c-ok)"},{"id":"no","label":"No congruentes","icon":"X","color":"var(--c-maiz-strong)"}],"items":[{"id":"a","text":"Las dos bases de un bote cilíndrico","bucket":"si"},{"id":"b","text":"La base cuadrada y una cara triangular de una pirámide","bucket":"no","feedback":"Un cuadrado y un triángulo no tienen la misma forma."},{"id":"c","text":"Dos caras opuestas de una caja","bucket":"si"},{"id":"d","text":"La cara de 30 × 20 y la de 30 × 10 de una caja","bucket":"no","feedback":"Son rectángulos, pero de distinto tamaño."},{"id":"e","text":"Dos caras cualesquiera de un dado","bucket":"si"}]},"id":"s03-mat-5-4"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.3.2"],"ambito":"conocer","title":"Contar caras congruentes","prompt":"La base regular no basta por sí sola: también importa dónde está la cúspide o si el prisma es recto. Toca cada ejemplo.","type":"explain","props":{"icon":"Hexagon","body":"En una **pirámide recta**, la cúspide está sobre el centro. En un **prisma recto**, las aristas laterales son perpendiculares a las bases.","reveal":[{"icon":"Hexagon","front":"Prisma recto de base hexagonal regular","back":"Tiene 2 hexágonos congruentes y **6 rectángulos laterales congruentes**: todos usan la misma altura y lados de base iguales."},{"icon":"Triangle","front":"Pirámide recta de base pentagonal regular","back":"Con la **cúspide sobre el centro**, tiene **5 triángulos laterales congruentes**."},{"icon":"Cone","front":"Cono","back":"Tiene **una sola** cara plana (la base): no hay pares congruentes."}]},"id":"s03-mat-5-5"},{"fase":"construir","areas":["mat"],"cnb":["mat:1.3.2"],"prompt":"Una **pirámide recta** tiene base cuadrada regular y la cúspide está sobre el centro. ¿Cuántas **caras laterales congruentes** tiene?","hint":"La condición de pirámide recta asegura que los triángulos laterales son iguales; hay uno por cada lado de la base.","explain":"Como la cúspide está sobre el centro y la base regular tiene 4 lados, hay 4 triángulos laterales congruentes.","type":"number-input","props":{"answer":4,"misconceptions":[{"value":5,"msg":"La base es un cuadrado, no un triángulo: no cuenta como cara lateral."}]},"id":"s03-mat-5-6"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.3.2"],"prompt":"Una caja mide **40 cm × 40 cm × 20 cm**: la tapa y el fondo son cuadrados de 40 × 40 y las demás caras miden 40 × 20. ¿Cuántas caras de **40 × 20** congruentes tiene?","explain":"Además de la tapa y el fondo (cuadrados), las 4 caras de alrededor miden 40 × 20: son 4 caras congruentes.","type":"number-input","props":{"answer":4,"misconceptions":[{"value":2,"msg":"Aquí el largo y el ancho son iguales, así que las 4 caras de alrededor son congruentes, no solo 2."}]},"id":"s03-mat-5-7"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.3.2","mat:1.3.1"],"prompt":"Une cada cuerpo con la descripción de sus caras congruentes.","explain":"Prismas y cilindros tienen dos bases congruentes. La congruencia de todas las caras laterales requiere las condiciones indicadas en los prismas y pirámides rectos.","type":"match","props":{"leftTitle":"Cuerpo","rightTitle":"Caras congruentes","pairs":[{"id":"p1","left":"Cubo","right":"6 cuadrados congruentes"},{"id":"p2","left":"Cilindro","right":"2 círculos congruentes"},{"id":"p3","left":"Pirámide recta de base triangular regular, cúspide sobre el centro","right":"3 caras laterales congruentes"},{"id":"p4","left":"Prisma recto de base hexagonal regular","right":"6 rectángulos congruentes y 2 bases"}]},"id":"s03-mat-5-8"},{"fase":"aplicar","areas":["mat"],"cnb":["mat:1.3.2"],"prompt":"Una caja tiene dos caras de 30 × 20 cm. Identifica esas caras y **justifica** por qué son congruentes.","type":"short-answer","props":{"minWords":8,"placeholder":"La tapa y el fondo son congruentes porque…","model":"La tapa y el fondo son congruentes porque ambos son rectángulos de 30 × 20 cm.","rubric":["Identifica el par de caras","Compara forma y medidas","Explica por qué son congruentes"]},"id":"s03-mat-5-9"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.3.2"],"prompt":"¿Qué cuerpo tiene **dos bases circulares congruentes**?","type":"choice","props":{"options":[{"id":"a","text":"Cono"},{"id":"b","text":"Cilindro"},{"id":"c","text":"Pirámide"}],"correct":["b"]},"id":"s03-mat-5-10"},{"fase":"comprobar","areas":["mat"],"cnb":["mat:1.3.2"],"prompt":"Un prisma recto tiene dos bases pentagonales iguales. ¿Qué opción **justifica** que son congruentes?","type":"choice","props":{"options":[{"id":"a","text":"Son congruentes porque tienen la misma forma pentagonal y las mismas medidas"},{"id":"b","text":"Son congruentes porque están en lados opuestos, aunque tengan medidas diferentes"},{"id":"c","text":"Son congruentes porque cualquier par de pentágonos tiene siempre el mismo tamaño"}],"correct":["a"]},"id":"s03-mat-5-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["mat"],"cnb":[],"type":"reflection","props":{"statements":["Reconozco simetría, traslación y rotación","Calculo el perímetro de polígonos","Cuento caras, aristas y vértices","Identifico caras congruentes en los cuerpos"],"commitments":["Buscaré movimientos geométricos en los tejidos y azulejos de mi casa","Mediré el perímetro de una mesa o una ventana","Contaré las caras de las cajas que encuentre"]},"id":"s03-mat-5-12"}],"kind":"materia","area":"mat","day":5}},{"missionId":"s03","version":"cnb-sexto-1c7d671a411baf00","lesson":{"id":"s03-cnt-3","title":"Glándulas: fábricas y mensajeros del cuerpo","icon":"HeartPulse","minutes":15,"gancho":"Antes de pasar al frente a leer, a Mariana le late rápido el corazón y le sudan las manos. ¿Quién da esa orden en su cuerpo?","objetivos":["Clasificar glándulas por su secreción y diferenciar glándulas sexuales masculinas y femeninas por su función"],"resumen":["Una glándula es un órgano que fabrica y libera sustancias.","Las glándulas de secreción interna (endocrinas) liberan hormonas a la sangre: hipófisis (glándula maestra, en la base del cerebro), tiroides (cuello), suprarrenales (sobre los riñones) y páncreas.","Las glándulas de secreción externa (exocrinas) sacan su producto por conductos hacia afuera del cuerpo o hacia una cavidad: sudoríparas, salivales, lagrimales, sebáceas y mamarias.","El páncreas es mixto: produce insulina, que va a la sangre, y jugo digestivo, que va al intestino.","Los testículos y los ovarios son glándulas endocrinas: los testículos producen principalmente testosterona y forman espermatozoides; los ovarios producen principalmente estrógenos y progesterona y contienen ovocitos."],"media":{"id":"s03-cnt-3-glandulas","kind":"diagram","title":"Mapa de las glándulas del cuerpo","aspect":"3:4","alt":"Silueta humana de frente con las glándulas marcadas: hipófisis en la cabeza, tiroides en el cuello, suprarrenales sobre los riñones y páncreas junto al estómago; y, en otro color, glándulas salivales, lagrimales y sudoríparas.","brief":"Diagrama vertical de una silueta humana neutra (sin rasgos sexuales). Marcar en MORADO las glándulas de secreción interna: hipófisis (base del cerebro), tiroides (cuello, forma de mariposa), suprarrenales (sombrero sobre cada riñón), páncreas (detrás del estómago, marcado como \\"mixta\\" con los dos colores). Marcar en VERDE las de secreción externa: lagrimales (ojos), salivales (junto a la mandíbula), sudoríparas (lupa sobre la piel). Leyenda: \\"morado = a la sangre (hormonas)\\", \\"verde = hacia afuera por conductos\\". Letra grande, fondo blanco. Dimensiones: 900x1200."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:2.3.1","cnt:2.3.2"],"ambito":"conocer","title":"¿Qué es una glándula?","prompt":"Una **glándula** fabrica y libera sustancias. Clasifica la vía de secreción y diferencia las glándulas sexuales masculinas y femeninas por su función.","type":"explain","props":{"icon":"Factory","body":"Liberar una sustancia se llama **secretar**. Los testículos y ovarios son endocrinos, pero cumplen funciones diferentes.","reveal":[{"icon":"HeartPulse","front":"Secreción interna (endocrinas)","back":"Liberan **hormonas** directamente a la **sangre**. Las hormonas son **mensajeros químicos**: viajan por todo el cuerpo y dan órdenes a otros órganos."},{"icon":"Droplets","front":"Secreción externa (exocrinas)","back":"Sacan su producto por **conductos** (tubitos) hacia **afuera del cuerpo** o hacia una cavidad, como la boca. Ejemplos: sudor, saliva, lágrimas."},{"icon":"Copy","front":"Glándula mixta","back":"El **páncreas** hace las dos cosas: envía **insulina** a la sangre y **jugo digestivo** al intestino."},{"icon":"Dna","front":"Testículos","back":"Glándulas sexuales masculinas: producen principalmente **testosterona** y forman **espermatozoides**."},{"icon":"Microscope","front":"Ovarios","back":"Glándulas sexuales femeninas: producen principalmente **estrógenos y progesterona** y contienen **ovocitos**."}]},"id":"s03-cnt-3-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.3.1"],"ambito":"conocer","prompt":"Cuando Mariana se pone nerviosa, su corazón late rápido en pocos segundos. ¿Qué crees que lo causa?","explain":"Unas glándulas liberan a la sangre una sustancia llamada **adrenalina**, que llega al corazón y lo acelera. Las sustancias que viajan por la sangre como mensajes se llaman **hormonas**.","type":"choice","props":{"options":[{"id":"a","text":"Una sustancia que su cuerpo liberó en la sangre","icon":"Droplet"},{"id":"b","text":"El frío del aula","icon":"Snowflake","feedback":"El frío no acelera el corazón de esa forma en unos segundos."},{"id":"c","text":"Algo que comió hace una semana","icon":"Utensils","feedback":"Es una respuesta inmediata, no por algo de hace días."}],"correct":["a"]},"id":"s03-cnt-3-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.3.1"],"ambito":"conocer","title":"Las glándulas de secreción interna","prompt":"Observa el mapa de la lección: las glándulas moradas envían hormonas a la sangre. Toca cada tarjeta.","type":"explain","props":{"icon":"Brain","body":"Aunque son pequeñas, sus hormonas controlan el **crecimiento**, la **energía**, el **azúcar de la sangre** y las **reacciones** ante el peligro.","reveal":[{"icon":"Crown","front":"Hipófisis","back":"En la **base del cerebro**; del tamaño de un frijol. Produce la **hormona del crecimiento** y da órdenes a otras glándulas: por eso la llaman **glándula maestra**."},{"icon":"Thermometer","front":"Tiroides","back":"En el **cuello**, con forma de mariposa. Sus hormonas regulan la **velocidad con que el cuerpo usa la energía**. Necesita **yodo**: por eso se usa sal yodada."},{"icon":"Zap","front":"Suprarrenales","back":"Como sombreritos **sobre los riñones**. Producen **adrenalina**, que prepara al cuerpo para reaccionar ante un susto o un peligro."},{"icon":"Candy","front":"Páncreas","back":"**Detrás del estómago**. Produce **insulina**, que ayuda a que el azúcar de la sangre entre a las células."}]},"id":"s03-cnt-3-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.3.1"],"ambito":"conocer","prompt":"Clasifica cada glándula según **hacia dónde** envía lo que produce.","hint":"Si su producto se ve o se siente afuera (sudor, lágrimas, saliva), es de secreción externa. Si produce hormonas, es interna.","explain":"Internas: hipófisis, tiroides, suprarrenales. Externas: sudoríparas, salivales, lagrimales. Mixta: páncreas.","type":"sort","props":{"buckets":[{"id":"int","label":"Secreción interna (a la sangre)","icon":"HeartPulse","color":"var(--area-fc)"},{"id":"ext","label":"Secreción externa (por conductos)","icon":"Droplets","color":"var(--c-ok)"},{"id":"mix","label":"Mixta","icon":"Copy","color":"var(--c-maiz-strong)"}],"items":[{"id":"g1","text":"Hipófisis","bucket":"int"},{"id":"g2","text":"Glándulas sudoríparas","bucket":"ext"},{"id":"g3","text":"Tiroides","bucket":"int"},{"id":"g4","text":"Glándulas salivales","bucket":"ext"},{"id":"g5","text":"Páncreas","bucket":"mix"},{"id":"g6","text":"Suprarrenales","bucket":"int"},{"id":"g7","text":"Glándulas lagrimales","bucket":"ext"}]},"id":"s03-cnt-3-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.3.1"],"ambito":"conocer","title":"Las glándulas de secreción externa","prompt":"Estas glándulas trabajan todos los días y casi no las notamos. Toca las tarjetas.","type":"explain","props":{"icon":"Droplets","body":"Sus productos protegen, limpian, enfrían o ayudan a digerir.","reveal":[{"icon":"Thermometer","front":"Sudoríparas (piel)","back":"Producen **sudor**. Al evaporarse de la piel, el sudor **enfría** el cuerpo."},{"icon":"Utensils","front":"Salivales (boca)","back":"Producen **saliva**, que humedece la comida y **empieza la digestión**."},{"icon":"Eye","front":"Lagrimales (ojos)","back":"Producen **lágrimas**, que **limpian y protegen** los ojos."},{"icon":"Shield","front":"Sebáceas (piel)","back":"Producen una **grasa** que protege la piel y el cabello. En la pubertad trabajan más: por eso aparecen granitos."},{"icon":"Milk","front":"Mamarias","back":"Producen **leche** para alimentar a los bebés después del parto."}]},"id":"s03-cnt-3-5"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.3.1"],"ambito":"conocer","prompt":"Ubica cada glándula: une con el **lugar** del cuerpo donde está.","hint":"Mira otra vez el mapa de glándulas de la lección.","explain":"Hipófisis: base del cerebro. Tiroides: cuello. Suprarrenales: sobre los riñones. Páncreas: detrás del estómago. Lagrimales: junto a los ojos.","type":"match","props":{"leftTitle":"Glándula","rightTitle":"Ubicación","pairs":[{"id":"h","left":"Hipófisis","right":"Base del cerebro"},{"id":"t","left":"Tiroides","right":"Cuello"},{"id":"s","left":"Suprarrenales","right":"Sobre los riñones"},{"id":"p","left":"Páncreas","right":"Detrás del estómago"},{"id":"l","left":"Lagrimales","right":"Junto a los ojos"}]},"id":"s03-cnt-3-6"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.3.1"],"ambito":"conocer","title":"Ejemplo: la adrenalina en acción","prompt":"Sigue paso a paso cómo una hormona funciona como **mensajero**.","media":{"id":"s03-cnt-3-adrenalina","kind":"animation","title":"Un susto y una hormona","aspect":"16:9","duration":35,"alt":"Animación: un perro ladra detrás de un niño; una señal viaja del cerebro a las suprarrenales; gotitas de adrenalina entran a la sangre y llegan al corazón, los pulmones y los músculos; luego todo se calma.","brief":"Animación 2D de 35 s, estilo amable. Un niño camina por la calle de su aldea; un perro ladra detrás de una puerta. Vista transparente del cuerpo: el cerebro envía una señal (rayo) a las glándulas suprarrenales, que liberan gotitas moradas (adrenalina) a la sangre. Las gotitas llegan al corazón (late más rápido, contador de latidos sube), a los pulmones (respira rápido) y a los músculos (brillan). El niño se da cuenta de que el perro está detrás de la puerta; en unos minutos todo vuelve a la calma. Narración en español con subtítulos."},"type":"worked-example","props":{"icon":"Zap","problem":"Un perro ladra de repente detrás de Mateo. En segundos, su corazón late rápido y siente mucha energía. ¿Qué pasó dentro de su cuerpo?","steps":[{"text":"Sus ojos y oídos detectan el peligro y el **cerebro** envía una señal a las **glándulas suprarrenales**."},{"text":"Las suprarrenales liberan **adrenalina** a la **sangre**.","why":"Son glándulas de secreción interna: su producto va a la sangre."},{"text":"La sangre lleva la adrenalina a todo el cuerpo: el **corazón** late más rápido, la **respiración** se acelera y los **músculos** reciben más energía.","why":"Así el cuerpo se prepara para huir o defenderse."},{"text":"Cuando el peligro pasa, el cuerpo deja de liberar adrenalina y todo **vuelve a la calma**."}],"answer":"Las **suprarrenales** liberaron **adrenalina** a la sangre, y esta llevó el mensaje de \\"¡prepárate!\\" a varios órganos.","tip":"Por eso sentimos el corazón acelerado antes de un examen: es la adrenalina. Respirar lento y profundo ayuda a calmarse."},"id":"s03-cnt-3-7"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:2.3.1"],"ambito":"conocer","prompt":"Después de jugar fútbol al mediodía, la camisa de Diego está mojada. ¿Qué glándulas trabajaron y de qué tipo son?","explain":"Las **sudoríparas** son de **secreción externa**: sacan el sudor por conductos hacia la piel, y al evaporarse enfría el cuerpo.","type":"choice","props":{"options":[{"id":"a","text":"Las sudoríparas, de secreción externa","icon":"Droplets"},{"id":"b","text":"La tiroides, de secreción externa","icon":"Thermometer","feedback":"La tiroides produce hormonas que van a la sangre: es de secreción interna, y no produce sudor."},{"id":"c","text":"Las sudoríparas, de secreción interna","icon":"HeartPulse","feedback":"El sudor sale por conductos hacia la piel: eso es secreción externa."}],"correct":["a"]},"id":"s03-cnt-3-8"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:2.3.1"],"ambito":"conocer","prompt":"Une cada glándula con lo que produce.","explain":"Hipófisis → hormona del crecimiento; páncreas → insulina; suprarrenales → adrenalina; sudoríparas → sudor; salivales → saliva.","type":"match","props":{"leftTitle":"Glándula","rightTitle":"Produce","pairs":[{"id":"h","left":"Hipófisis","right":"Hormona del crecimiento"},{"id":"p","left":"Páncreas","right":"Insulina"},{"id":"s","left":"Suprarrenales","right":"Adrenalina"},{"id":"d","left":"Sudoríparas","right":"Sudor"},{"id":"v","left":"Salivales","right":"Saliva"}]},"id":"s03-cnt-3-9"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:2.3.1","cnt:2.3.2"],"ambito":"conocer","prompt":"Testículos y ovarios son glándulas endocrinas que liberan hormonas a la sangre. ¿Qué diferencia funcional distingue las glándulas sexuales masculinas de las femeninas?","explain":"Ambas son endocrinas. Los testículos producen principalmente testosterona y forman espermatozoides; los ovarios producen principalmente estrógenos y progesterona y contienen ovocitos.","type":"choice","props":{"options":[{"id":"a","text":"Testículos: testosterona y espermatozoides; ovarios: estrógenos, progesterona y ovocitos","icon":"GitCompare"},{"id":"b","text":"Los ovarios producen sudor y los testículos producen lágrimas","icon":"Droplets"},{"id":"c","text":"No existe diferencia funcional entre ambas glándulas","icon":"Equal"}],"correct":["a"]},"id":"s03-cnt-3-10"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:2.3.1","cnt:2.3.2"],"prompt":"¿Qué opción clasifica la vía endocrina y diferencia correctamente glándulas sexuales masculinas y femeninas?","type":"choice","props":{"options":[{"id":"a","text":"Liberan hormonas a la sangre; los testículos forman espermatozoides y los ovarios contienen ovocitos"},{"id":"b","text":"Usan conductos hacia la piel y cumplen exactamente la misma función"},{"id":"c","text":"Solo los ovarios son glándulas"}],"correct":["a"]},"id":"s03-cnt-3-11"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:2.3.1","cnt:2.3.2"],"prompt":"Comprueba la clasificación endocrina y la diferencia funcional entre glándulas sexuales masculinas y femeninas.","type":"true-false","props":{"statements":[{"text":"Testículos y ovarios liberan hormonas a la sangre.","answer":true},{"text":"Los testículos forman espermatozoides y los ovarios contienen ovocitos.","answer":true},{"text":"Las dos glándulas producen exactamente las mismas hormonas y células.","answer":false}]},"id":"s03-cnt-3-12"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["cnt"],"cnb":[],"type":"reflection","props":{"statements":["Clasifico animales en vertebrados e invertebrados","Explico por qué hay diversidad de seres vivos","Ubico glándulas y distingo las de secreción interna y externa"],"commitments":["Observaré los animales de mi comunidad y los clasificaré","Respiraré lento y profundo cuando sienta nervios"]},"id":"s03-cnt-3-13"}],"kind":"materia","area":"cnt","day":5}},{"missionId":"s03","version":"cnb-sexto-1d53e6396115b3a0","lesson":{"id":"s03-fc-2","title":"Pensar críticamente ante la discriminación","icon":"Search","minutes":15,"gancho":"\\"Las niñas no saben jugar fútbol.\\" \\"Los de ese pueblo son haraganes.\\" ¿Has escuchado frases así? ¿Son verdad?","objetivos":["Responder críticamente y con respeto ante argumentos que justifican la discriminación"],"resumen":["Estereotipo: idea simplificada sobre un grupo (\\"todos los… son…\\"). Prejuicio: juzgar a alguien antes de conocerlo, por su grupo. Discriminación: tratar peor a alguien por su pueblo, idioma, sexo, religión, discapacidad o pobreza.","Machismo: creer que los hombres valen más que las mujeres. Sexismo: dar distinto trato u oportunidades por ser hombre o mujer. Racismo y discriminación étnica: despreciar a alguien por su pueblo, color de piel o cultura.","Un argumento discriminatorio generaliza, juzga por el grupo y no por la persona, y convierte una diferencia en inferioridad. Se responde pidiendo pruebas, dando contraejemplos y recordando la igualdad de derechos.","La Constitución de Guatemala (artículo 4) dice que todos los seres humanos son libres e iguales en dignidad y derechos. La discriminación es un delito en el Código Penal."],"media":{"id":"s03-fc-2-lupa","kind":"animation","title":"La lupa del pensamiento crítico","aspect":"16:9","duration":45,"alt":"Una frase discriminatoria aparece en un globo de diálogo; una lupa la examina y señala la generalización, luego aparece una respuesta respetuosa con un contraejemplo.","brief":"Animación 2D de 45 s. Aparece un globo de diálogo: \\"Todas las niñas son malas para las matemáticas\\". Una lupa se acerca y resalta en amarillo la palabra \\"Todas\\" con la etiqueta \\"generalización\\". Luego aparecen tres ejemplos de niñas resolviendo problemas, construyendo y programando: \\"contraejemplos\\". Finalmente un nuevo globo: \\"Cada persona es distinta; las capacidades no dependen del sexo\\". Narración en español, subtítulos. Colores suaves, personajes diversos."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:1.2.3"],"ambito":"conocer","title":"De la idea al daño","prompt":"La discriminación casi siempre empieza con una **idea equivocada** en la cabeza. Mira cómo avanza. Toca cada tarjeta en orden.","type":"explain","props":{"icon":"Layers","body":"Si frenamos la idea a tiempo, frenamos el daño. Por eso importa **pensar críticamente**.","reveal":[{"icon":"Brain","front":"1. Estereotipo","back":"Una idea **simplificada** sobre un grupo: \\"Todos los de la capital son…\\", \\"Las mujeres son…\\". Borra las diferencias entre personas."},{"icon":"Eye","front":"2. Prejuicio","back":"**Juzgar** a alguien antes de conocerlo, solo por el grupo al que pertenece. \\"No la invito: seguro no sabe.\\""},{"icon":"X","front":"3. Discriminación","back":"**Tratar peor** a alguien por su pueblo, idioma, sexo, religión, discapacidad o pobreza: excluirlo, burlarse, negarle una oportunidad."}]},"id":"s03-fc-2-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.3"],"ambito":"conocer","prompt":"Un compañero dice: **\\"Las niñas no saben jugar fútbol.\\"** ¿Qué le responderías?","explain":"Muchas niñas juegan fútbol muy bien, y en Guatemala hay selecciones y ligas femeninas. La frase **generaliza**: habla de \\"las niñas\\" como si todas fueran iguales. Hoy aprenderás a detectar y responder frases así.","type":"choice","props":{"options":[{"id":"a","text":"Que eso no es cierto: jugar bien depende de practicar, no de ser niña o niño","icon":"Scale"},{"id":"b","text":"Que tiene razón, siempre ha sido así","icon":"ThumbsUp","feedback":"Que algo \\"siempre se haya dicho\\" no lo hace verdad. Piensa en niñas que conoces que juegan bien."}],"correct":["a"]},"id":"s03-fc-2-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.3"],"ambito":"conocer","title":"Formas de discriminación que hay que nombrar","prompt":"Poner nombre a las cosas ayuda a reconocerlas. Toca cada tarjeta.","type":"explain","props":{"icon":"Search","body":"Todas estas formas van contra la **igualdad**. La Constitución de Guatemala, en su **artículo 4**, dice que **todos los seres humanos son libres e iguales en dignidad y derechos**, y que hombres y mujeres tienen iguales oportunidades y responsabilidades.","reveal":[{"icon":"User","front":"Machismo","back":"Creer que los **hombres valen más** que las mujeres o que deben mandar sobre ellas. \\"Eso es cosa de hombres.\\""},{"icon":"Users","front":"Sexismo","back":"Dar **distinto trato u oportunidades** a alguien por ser hombre o mujer. \\"Las niñas limpian, los niños cargan.\\""},{"icon":"Hand","front":"Racismo","back":"Creer que hay personas **superiores o inferiores** por su color de piel u origen, y tratarlas en consecuencia."},{"icon":"Languages","front":"Discriminación étnica","back":"Despreciar a alguien por su **pueblo, idioma o traje**. Por ejemplo, burlarse de quien usa güipil o habla un idioma maya."}]},"id":"s03-fc-2-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.3"],"prompt":"Clasifica cada frase o acción según el tipo de discriminación.","hint":"¿Se desprecia a alguien por ser mujer (machismo o sexismo) o por su pueblo, color o idioma (racismo o discriminación étnica)?","explain":"Machismo y sexismo discriminan por el sexo; racismo y discriminación étnica, por el origen, el color de piel, el idioma o la cultura.","type":"sort","props":{"buckets":[{"id":"sex","label":"Machismo o sexismo","icon":"Users","color":"var(--area-fc)"},{"id":"rac","label":"Racismo o discriminación étnica","icon":"Languages","color":"var(--c-maiz-strong)"}],"items":[{"id":"f1","text":"\\"Las mujeres no deberían manejar camionetas.\\"","bucket":"sex"},{"id":"f2","text":"No atender a una señora en la tienda porque habla mam","bucket":"rac"},{"id":"f3","text":"\\"En esta casa los hombres no lavan platos.\\"","bucket":"sex"},{"id":"f4","text":"Poner apodos a un compañero por su color de piel","bucket":"rac"},{"id":"f5","text":"Pagarle menos a una mujer por hacer el mismo trabajo que un hombre","bucket":"sex","feedback":"Es sexismo: el trabajo es el mismo, pero se paga distinto solo por ser mujer."},{"id":"f6","text":"Decir que el traje maya \\"se ve feo\\" y pedir que no lo usen en la escuela","bucket":"rac"}]},"id":"s03-fc-2-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.3"],"ambito":"hacer","title":"Ejemplo resuelto: desarmar un argumento discriminatorio","prompt":"Algunas personas intentan **justificar** la discriminación con \\"argumentos\\". Mira cómo analizarlos con tres preguntas.","type":"worked-example","props":{"icon":"Search","problem":"En una reunión alguien dice: **\\"No elijamos a una mujer como presidenta del comité, porque las mujeres son muy sentimentales para mandar.\\"**","steps":[{"text":"**¿Generaliza?** Sí: habla de \\"las mujeres\\" como si todas fueran iguales.","why":"Las palabras \\"todos\\", \\"todas\\", \\"siempre\\", \\"nunca\\" son una alerta."},{"text":"**¿Juzga por el grupo y no por la persona?** Sí: no revisa si esa candidata en concreto tiene experiencia, ideas o honestidad."},{"text":"**¿Convierte una diferencia en inferioridad?** Sí: supone que sentir emociones impide dirigir. Todas las personas, hombres y mujeres, sienten emociones."},{"text":"**Respondo con argumentos:** \\"Hay mujeres que dirigen muy bien comités, municipalidades y empresas. Elijamos por las propuestas y la honestidad de cada candidato, no por su sexo.\\""}],"answer":"El argumento es **machista**: generaliza, juzga por el grupo y convierte una diferencia en inferioridad. Se responde con **contraejemplos** y con el principio de **igualdad**.","tip":"Tres preguntas: ¿generaliza? ¿juzga por el grupo? ¿convierte la diferencia en inferioridad?"},"id":"s03-fc-2-5"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.3"],"prompt":"Toca las **palabras que generalizan** en estas frases. Son la primera alerta de un estereotipo.","hint":"Busca palabras que hablan de un grupo entero o de \\"siempre/nunca\\".","explain":"\\"Todos\\", \\"todas\\", \\"siempre\\", \\"nunca\\" y \\"ninguno\\" convierten a muchas personas distintas en una sola idea. Por eso son una alerta.","type":"highlight","props":{"target":"palabras que generalizan","text":"{Todos} los jóvenes son irresponsables. Las niñas {nunca} entienden de computadoras. {Ninguno} de esa aldea sabe leer bien. En la ciudad la gente {siempre} es egoísta."},"id":"s03-fc-2-6"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.3"],"ambito":"convivir","prompt":"¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"MessageCircle","text":"En la cancha, **Kevin** dice: \\"Las niñas no pueden ser capitanas del equipo porque no saben mandar\\". Varias niñas quieren postularse y se quedan calladas."},"options":[{"id":"a","icon":"ThumbsUp","text":"Darle la razón a Kevin para no pelear","consequence":"Las niñas se quedan fuera y se repite una idea falsa y machista.","values":["Machismo","Silencio"],"constructive":false},{"id":"b","icon":"Scale","text":"Preguntarle a Kevin: \\"¿Por qué lo dices? ¿Conoces a todas las niñas?\\" y proponer elegir por quién organiza mejor al equipo","consequence":"Kevin no tiene pruebas. El grupo acuerda elegir por capacidades y una niña es elegida capitana.","values":["Pensamiento crítico","Equidad"],"constructive":true},{"id":"c","icon":"Users","text":"Proponer que la capitanía rote entre niñas y niños cada semana","consequence":"Todas y todos practican el liderazgo. Kevin descubre que sus compañeras organizan muy bien.","values":["Inclusión","Igualdad de oportunidades"],"constructive":true}]},"id":"s03-fc-2-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.3"],"prompt":"Alguien dice: **\\"Si hablas un idioma maya, te va a costar aprender inglés.\\"** ¿Cuál es la respuesta **más crítica y respetuosa**?","explain":"La frase no tiene pruebas: hablar varios idiomas **no** es un obstáculo; muchas personas bilingües aprenden un tercer idioma con facilidad. Pedir pruebas y dar contraejemplos es pensar críticamente.","type":"choice","props":{"options":[{"id":"a","text":"\\"¿En qué te basas? Conozco personas que hablan k’iche’, español e inglés. Saber varios idiomas ayuda a aprender otro.\\""},{"id":"b","text":"\\"Tienes razón, mejor que dejen de hablar su idioma.\\"","feedback":"Eso sería aceptar un prejuicio y perder una riqueza. No hay pruebas de lo que dice la frase."},{"id":"c","text":"\\"¡Qué tonto eres!\\"","feedback":"Insultar no convence y también es falta de respeto. Mejor responde con argumentos."}],"correct":["a"]},"id":"s03-fc-2-8"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.3","fc:2.1.1"],"ambito":"conocer","prompt":"Lee y responde. Este texto muestra qué dicen las leyes y los Acuerdos de Paz sobre la discriminación.","type":"reading","props":{"genre":"Texto informativo","heading":"La igualdad también está en la ley","passage":"La **Constitución Política de la República de Guatemala**, en su **artículo 4**, dice que en Guatemala todos los seres humanos son libres e iguales en dignidad y derechos, y que el hombre y la mujer tienen iguales oportunidades y responsabilidades.\\n\\nEn **1995** se firmó el **Acuerdo sobre Identidad y Derechos de los Pueblos Indígenas**, uno de los Acuerdos de Paz. Ese acuerdo reconoce que Guatemala es una nación multiétnica, pluricultural y multilingüe, y pide eliminar la discriminación contra los pueblos indígenas. Además, reconoce que las **mujeres indígenas** han sufrido una **doble discriminación**: por ser mujeres y por ser indígenas.\\n\\nHoy, en Guatemala, la discriminación es un **delito** en el Código Penal. Pero las leyes no bastan: la igualdad también se construye en el aula, en la cancha y en la casa, cada vez que alguien se atreve a decir \\"eso no es justo\\".","questions":[{"q":"¿Qué dice el artículo 4 de la Constitución?","options":[{"id":"a","text":"Que todos los seres humanos son libres e iguales en dignidad y derechos"},{"id":"b","text":"Que solo algunas personas tienen derechos"},{"id":"c","text":"Que los hombres tienen más oportunidades que las mujeres"}],"correct":"a"},{"q":"¿Por qué el Acuerdo habla de \\"doble discriminación\\" de las mujeres indígenas?","options":[{"id":"a","text":"Porque pueden ser discriminadas por ser mujeres y también por ser indígenas"},{"id":"b","text":"Porque tienen dos nombres"},{"id":"c","text":"Porque hablan dos idiomas"}],"correct":"a"},{"q":"Según el último párrafo, ¿qué más hace falta además de las leyes?","options":[{"id":"a","text":"Que las personas practiquen la igualdad en la vida diaria y se atrevan a señalar lo injusto"},{"id":"b","text":"Nada, las leyes lo resuelven todo"},{"id":"c","text":"Esperar a ser adultos"}],"correct":"a","why":"La igualdad se construye con leyes y también con actitudes de cada día."}]},"id":"s03-fc-2-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.2.3"],"prompt":"\\"Mi hermana no puede estudiar mecánica porque es mujer.\\" Esta frase es un ejemplo de…","type":"choice","props":{"options":[{"id":"a","text":"Sexismo o machismo"},{"id":"b","text":"Tolerancia"},{"id":"c","text":"Solidaridad"}],"correct":["a"]},"id":"s03-fc-2-10"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.2.3"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Un prejuicio es juzgar a alguien antes de conocerlo, solo por su grupo.","answer":true},{"text":"Las palabras \\"todos\\" y \\"nunca\\" pueden ser una alerta de estereotipo.","answer":true},{"text":"Burlarse del traje o del idioma de alguien es discriminación étnica.","answer":true},{"text":"Si una idea se ha repetido por muchos años, entonces es verdad.","answer":false,"why":"Que algo se repita no lo hace cierto: hay que pedir pruebas."}]},"id":"s03-fc-2-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["fc"],"cnb":["fc:1.2.3","fc:2.1.1"],"type":"reflection","props":{"statements":["Nombro los cuatro pueblos y los 25 idiomas de Guatemala","Distingo estereotipo, prejuicio y discriminación","Respondo con argumentos a una frase discriminatoria"],"commitments":["Preguntaré en casa qué idiomas hablaban mis abuelos","Cuando escuche \\"todos los… son…\\", preguntaré en qué se basa","Invitaré a participar a alguien que suele quedar excluido"]},"id":"s03-fc-2-12"}],"kind":"materia","area":"fc","day":5}},{"missionId":"s03","version":"cnb-sexto-d8a09325ef99cf8b","lesson":{"id":"s03-ef-2","title":"Mi cuerpo en el espacio: direcciones, niveles y expresión","icon":"PersonStanding","minutes":15,"gancho":"Sin decir una palabra, ¿podrías mostrar con tu cuerpo que tienes miedo, que estás feliz o que eres un volcán a punto de despertar?","objetivos":["Crear una secuencia expresiva usando direcciones, niveles, trayectorias, velocidad e intención"],"resumen":["Relaciones espacio-temporales: el cuerpo se mueve en direcciones (adelante, atrás, a los lados, arriba, abajo), niveles (alto, medio, bajo) y trayectorias (recta, curva, zigzag), a distintas velocidades (rápido, lento) y duraciones.","Recursos expresivos: el gesto (cara y manos), la mirada, la postura, la energía (movimiento fuerte o suave) y la velocidad.","La plasticidad es la capacidad del cuerpo de tomar muchas formas; la intencionalidad es lo que quieres comunicar con cada movimiento.","Una secuencia de movimiento tiene inicio (posición quieta), desarrollo y final (posición quieta), y se puede contar en estructuras de 8 tiempos."],"media":{"id":"s03-ef-2-expresion","kind":"video","title":"El cuerpo que comunica","aspect":"16:9","duration":50,"alt":"Una niña representa la milpa: empieza agachada en nivel bajo como semilla, crece lentamente hasta nivel alto con los brazos como hojas, se mueve en curva con el viento y cae suave con la cosecha.","brief":"Video de 50 s en un salón despejado con luz natural. Una niña y un niño (ropa sencilla, rostros visibles solo con permiso o en silueta) interpretan \\"El ciclo de la milpa\\" sin palabras, con marimba suave de fondo: (1) semilla en nivel bajo, cuerpo cerrado; (2) crecimiento lento a nivel medio y alto; (3) viento: trayectoria curva, balanceo; (4) lluvia fuerte: movimientos rápidos y enérgicos en zigzag; (5) cosecha: caída suave y pausa final. Rótulos breves: \\"nivel bajo\\", \\"lento\\", \\"curva\\", \\"energía fuerte\\", \\"posición final\\". Ninguna vestimenta de una comunidad concreta. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:1.4.2"],"ambito":"conocer","title":"El cuerpo en el espacio y el tiempo","prompt":"Para moverte con intención, piensa **dónde** y **cuándo** te mueves. Toca cada tarjeta y pruébalo.","type":"explain","props":{"icon":"Compass","body":"Estas son las **relaciones espacio-temporales**: los \\"ingredientes\\" de cualquier movimiento.","reveal":[{"icon":"Compass","front":"Direcciones","back":"Adelante, atrás, a la derecha, a la izquierda, arriba y abajo."},{"icon":"Layers","front":"Niveles","back":"**Bajo** (en el suelo, agachado), **medio** (rodillas dobladas, inclinado) y **alto** (de pie, de puntillas, saltando)."},{"icon":"Route","front":"Trayectorias","back":"El camino que dibujas en el suelo: **recta**, **curva**, **zigzag**, **círculo**."},{"icon":"Timer","front":"Velocidad y duración","back":"Rápido o lento, largo o corto. Puedes moverte **en 8 tiempos** o **en 2**, y eso cambia la sensación."}]},"id":"s03-ef-2-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.12"],"ambito":"conocer","prompt":"En el video, la niña empieza **agachada, cerrada y quieta**. ¿Qué crees que representa?","explain":"Una **semilla**. Sin palabras, usó el **nivel bajo**, la **postura cerrada** y la **quietud**. El cuerpo es un lenguaje: hoy aprenderás sus \\"palabras\\".","type":"choice","props":{"options":[{"id":"a","text":"Una semilla bajo la tierra","icon":"Sprout"},{"id":"b","text":"Una persona corriendo","icon":"Footprints","feedback":"Correr necesita movimiento y desplazamiento; ella está quieta y en el suelo."},{"id":"c","text":"Un árbol muy alto","icon":"TreePine","feedback":"Un árbol alto usaría el nivel alto, con el cuerpo estirado."}],"correct":["a"]},"id":"s03-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.12"],"ambito":"conocer","title":"Los recursos expresivos","prompt":"Actores, danzantes y deportistas usan el cuerpo para **comunicar**. Toca cada recurso.","type":"explain","props":{"icon":"Smile","body":"La **plasticidad** es la capacidad del cuerpo de tomar muchas formas. La **intencionalidad** es **lo que quieres decir** con cada forma.","reveal":[{"icon":"Smile","front":"Gesto","back":"Lo que hacen la **cara** y las **manos**: sonreír, fruncir el ceño, abrir las palmas."},{"icon":"Eye","front":"Mirada","back":"A dónde miras dice mucho: arriba (esperanza), abajo (tristeza o timidez), al público (seguridad)."},{"icon":"PersonStanding","front":"Postura","back":"Cuerpo **abierto** y erguido (alegría, fuerza) o **cerrado** y encogido (miedo, frío, tristeza)."},{"icon":"Zap","front":"Energía","back":"Movimiento **fuerte** y cortante (enojo, tormenta) o **suave** y fluido (calma, agua, viento)."},{"icon":"Gauge","front":"Velocidad","back":"**Rápido** transmite prisa, emoción o nervios; **lento**, calma, cansancio o solemnidad."}]},"id":"s03-ef-2-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.2","ef:1.4.12"],"ambito":"hacer","title":"Ejemplo resuelto: la secuencia \\"El volcán despierta\\"","prompt":"Mira cómo Julio arma una secuencia de **4 partes de 8 tiempos** con una intención clara.","type":"worked-example","props":{"icon":"Mountain","problem":"Julio quiere mostrar, sin palabras, un volcán que duerme, despierta, hace erupción y vuelve a la calma.","steps":[{"text":"**Inicio (8 tiempos):** nivel **bajo**, postura cerrada, quieto; solo respira despacio. Intención: el volcán duerme."},{"text":"**Parte 2 (8 tiempos):** sube **lentamente** al nivel medio, temblando un poco los brazos. Intención: el volcán despierta.","why":"La velocidad lenta y el temblor crean suspenso."},{"text":"**Parte 3 (8 tiempos):** salta al nivel **alto**, brazos que se abren **rápido y con energía fuerte** hacia arriba y en **zigzag**. Intención: la erupción."},{"text":"**Final (8 tiempos):** baja en **trayectoria curva**, con movimientos **suaves**, hasta quedar quieto en nivel bajo. Intención: la lava se enfría y vuelve la calma."}],"answer":"Julio combinó **niveles, velocidad, energía y trayectorias** con una **intención** clara en cada parte, en 4 × 8 = 32 tiempos.","tip":"Empieza y termina siempre con una posición quieta: el público entiende dónde empieza y dónde acaba la historia."},"id":"s03-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.12"],"ambito":"hacer","prompt":"Une cada idea que quieres comunicar con el recurso expresivo que mejor la muestra.","hint":"Piensa en la postura, la energía y la velocidad de cada emoción.","explain":"Cada recurso tiene una intención: la postura cerrada comunica frío o miedo, la energía fuerte enojo o fuerza, la lentitud calma o cansancio.","type":"match","props":{"leftTitle":"Quiero comunicar…","rightTitle":"Recurso","pairs":[{"id":"f","left":"Tengo mucho frío","right":"Postura cerrada y temblorosa"},{"id":"t","left":"Llega una tormenta","right":"Energía fuerte y movimientos rápidos"},{"id":"c","left":"El agua del lago en calma","right":"Movimientos suaves, lentos y curvos"},{"id":"a","left":"¡Ganamos el partido!","right":"Postura abierta, brazos arriba y sonrisa"}]},"id":"s03-ef-2-5"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.4.2","ef:1.4.12"],"ambito":"hacer","prompt":"¡Tu secuencia! **Calentamiento:** muévete por el espacio en trayectoria recta, curva y zigzag (20 s cada una), cambiando de nivel cuando alguien diga \\"¡bajo!\\", \\"¡medio!\\", \\"¡alto!\\". **Parte principal:** crea tu propia secuencia de **4 partes de 8 tiempos** sobre uno de estos temas: \\"La milpa crece\\", \\"Un día de lluvia\\" o \\"El río baja de la montaña\\". Usa al menos 2 niveles, 2 trayectorias y cambios de velocidad. Repítela 3 veces hasta que te salga fluida y muéstrasela a alguien. **Poco espacio:** usa más los niveles que el desplazamiento. **Adaptación:** en silla de ruedas, usa brazos, tronco, cabeza y giros de la silla. **Vuelta a la calma:** estira y respira.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después del calentamiento en el espacio","exercise":{"name":"Trayectorias y niveles","icon":"Route","seconds":60}},{"label":"Después de tu secuencia (3 veces)","exercise":{"name":"Secuencia expresiva de 4 × 8 tiempos","icon":"Sparkles","seconds":90}}]},"id":"s03-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.4.2","ef:1.4.12"],"ambito":"hacer","prompt":"Escribe el **guion de tu secuencia**: el tema, y en cada una de las 4 partes de 8 tiempos, qué **nivel**, **trayectoria**, **velocidad** y **energía** usaste y qué querías **comunicar**.","type":"short-answer","props":{"minWords":40,"placeholder":"Mi tema es… Parte 1: … Parte 2: … Parte 3: … Parte 4: …","model":"Mi tema es \\"El río baja de la montaña\\". Parte 1: nivel alto, de puntillas, movimientos suaves; soy el agua que nace arriba. Parte 2: nivel medio, trayectoria en zigzag y más rápido; el río baja entre piedras. Parte 3: nivel bajo, energía fuerte, brazos que empujan; es una crecida por la lluvia. Parte 4: trayectoria curva, lento y suave hasta quedar quieta; el río llega tranquilo al lago.","rubric":["Tiene un tema claro","Describe 4 partes de 8 tiempos","Usa al menos 2 niveles y 2 trayectorias","Explica la intención de cada parte"]},"id":"s03-ef-2-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.4.2","ef:1.4.12"],"ambito":"hacer","prompt":"Para representar a una persona que avanza con cautela por una ruta estrecha, ¿qué secuencia comunica mejor esa intención?","type":"choice","props":{"options":[{"id":"a","text":"Pasos lentos en línea curva, nivel medio, mirada al frente y energía suave"},{"id":"b","text":"Saltos rápidos sin mirar, con giros amplios y energía fuerte"},{"id":"c","text":"Quedarse inmóvil de espaldas durante toda la secuencia"}],"correct":["a"]},"id":"s03-ef-2-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.4.2"],"prompt":"Te mueves **agachado**, con las rodillas muy dobladas y las manos cerca del suelo. ¿En qué nivel estás?","type":"choice","props":{"options":[{"id":"a","text":"Nivel alto"},{"id":"b","text":"Nivel medio"},{"id":"c","text":"Nivel bajo"}],"correct":["c"]},"id":"s03-ef-2-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.4.2","ef:1.4.12"],"prompt":"Clasifica cada elemento: ¿es una **relación espacio-temporal** o un **recurso expresivo**?","type":"sort","props":{"buckets":[{"id":"e","label":"Espacio-tiempo","icon":"Compass","color":"var(--area-ef)"},{"id":"x","label":"Recurso expresivo","icon":"Smile","color":"var(--c-maiz-strong)"}],"items":[{"id":"y1","text":"Trayectoria en zigzag","bucket":"e"},{"id":"y2","text":"Mirada hacia abajo","bucket":"x"},{"id":"y3","text":"Nivel alto","bucket":"e"},{"id":"y4","text":"Gesto de sorpresa","bucket":"x"},{"id":"y5","text":"Postura encogida","bucket":"x"}]},"id":"s03-ef-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Sé honesto: aprender es un camino.","areas":["ef"],"cnb":["ef:1.4.12"],"type":"reflection","props":{"statements":["Marcho y troto siguiendo el pulso de la música","Uso niveles, direcciones y trayectorias","Comunico una idea con gestos, postura, energía y velocidad"],"commitments":["Practicaré mi patrón de 8 tiempos con una canción","Presentaré mi secuencia a mi familia","Observaré cómo se mueven los danzantes en las fiestas de mi comunidad"]},"id":"s03-ef-2-11"}],"kind":"materia","area":"ef","day":5}},{"missionId":"s03","version":"cnb-sexto-1f441274b5ef47be","lesson":{"id":"s03-ef-2","title":"Mi cuerpo en el espacio: direcciones, niveles y expresión","icon":"PersonStanding","minutes":15,"gancho":"Sin decir una palabra, ¿podrías mostrar con tu cuerpo que tienes miedo, que estás feliz o que eres un volcán a punto de despertar?","objetivos":["Crear una secuencia expresiva usando direcciones, niveles, trayectorias, velocidad e intención"],"resumen":["Relaciones espacio-temporales: el cuerpo se mueve en direcciones (adelante, atrás, a los lados, arriba, abajo), niveles (alto, medio, bajo) y trayectorias (recta, curva, zigzag), a distintas velocidades (rápido, lento) y duraciones.","Recursos expresivos: el gesto (cara y manos), la mirada, la postura, la energía (movimiento fuerte o suave) y la velocidad.","La plasticidad es la capacidad del cuerpo de tomar muchas formas; la intencionalidad es lo que quieres comunicar con cada movimiento.","Una secuencia de movimiento tiene inicio (posición quieta), desarrollo y final (posición quieta), y se puede contar en estructuras de 8 tiempos."],"media":{"id":"s03-ef-2-expresion","kind":"video","title":"El cuerpo que comunica","aspect":"16:9","duration":50,"alt":"Una niña representa la milpa: empieza agachada en nivel bajo como semilla, crece lentamente hasta nivel alto con los brazos como hojas, se mueve en curva con el viento y cae suave con la cosecha.","brief":"Video de 50 s en un salón despejado con luz natural. Una niña y un niño (ropa sencilla, rostros visibles solo con permiso o en silueta) interpretan \\"El ciclo de la milpa\\" sin palabras, con marimba suave de fondo: (1) semilla en nivel bajo, cuerpo cerrado; (2) crecimiento lento a nivel medio y alto; (3) viento: trayectoria curva, balanceo; (4) lluvia fuerte: movimientos rápidos y enérgicos en zigzag; (5) cosecha: caída suave y pausa final. Rótulos breves: \\"nivel bajo\\", \\"lento\\", \\"curva\\", \\"energía fuerte\\", \\"posición final\\". Ninguna vestimenta de una comunidad concreta. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:1.4.2"],"ambito":"conocer","title":"El cuerpo en el espacio y el tiempo","prompt":"Para moverte con intención, piensa **dónde** y **cuándo** te mueves. Toca cada tarjeta y pruébalo.","type":"explain","props":{"icon":"Compass","body":"Estas son las **relaciones espacio-temporales**: los \\"ingredientes\\" de cualquier movimiento.","reveal":[{"icon":"Compass","front":"Direcciones","back":"Adelante, atrás, a la derecha, a la izquierda, arriba y abajo."},{"icon":"Layers","front":"Niveles","back":"**Bajo** (en el suelo, agachado), **medio** (rodillas dobladas, inclinado) y **alto** (de pie, de puntillas, saltando)."},{"icon":"Route","front":"Trayectorias","back":"El camino que dibujas en el suelo: **recta**, **curva**, **zigzag**, **círculo**."},{"icon":"Timer","front":"Velocidad y duración","back":"Rápido o lento, largo o corto. Puedes moverte **en 8 tiempos** o **en 2**, y eso cambia la sensación."}]},"id":"s03-ef-2-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.12"],"ambito":"conocer","prompt":"En el video, la niña empieza **agachada, cerrada y quieta**. ¿Qué crees que representa?","explain":"Una **semilla**. Sin palabras, usó el **nivel bajo**, la **postura cerrada** y la **quietud**. El cuerpo es un lenguaje: hoy aprenderás sus \\"palabras\\".","type":"choice","props":{"options":[{"id":"a","text":"Una semilla bajo la tierra","icon":"Sprout"},{"id":"b","text":"Una persona corriendo","icon":"Footprints","feedback":"Correr necesita movimiento y desplazamiento; ella está quieta y en el suelo."},{"id":"c","text":"Un árbol muy alto","icon":"TreePine","feedback":"Un árbol alto usaría el nivel alto, con el cuerpo estirado."}],"correct":["a"]},"id":"s03-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.12"],"ambito":"conocer","title":"Los recursos expresivos","prompt":"Actores, danzantes y deportistas usan el cuerpo para **comunicar**. Toca cada recurso.","type":"explain","props":{"icon":"Smile","body":"La **plasticidad** es la capacidad del cuerpo de tomar muchas formas. La **intencionalidad** es **lo que quieres decir** con cada forma.","reveal":[{"icon":"Smile","front":"Gesto","back":"Lo que hacen la **cara** y las **manos**: sonreír, fruncir el ceño, abrir las palmas."},{"icon":"Eye","front":"Mirada","back":"A dónde miras dice mucho: arriba (esperanza), abajo (tristeza o timidez), al público (seguridad)."},{"icon":"PersonStanding","front":"Postura","back":"Cuerpo **abierto** y erguido (alegría, fuerza) o **cerrado** y encogido (miedo, frío, tristeza)."},{"icon":"Zap","front":"Energía","back":"Movimiento **fuerte** y cortante (enojo, tormenta) o **suave** y fluido (calma, agua, viento)."},{"icon":"Gauge","front":"Velocidad","back":"**Rápido** transmite prisa, emoción o nervios; **lento**, calma, cansancio o solemnidad."}]},"id":"s03-ef-2-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.2","ef:1.4.12"],"ambito":"hacer","title":"Ejemplo resuelto: la secuencia \\"El volcán despierta\\"","prompt":"Mira cómo Julio arma una secuencia de **4 partes de 8 tiempos** con una intención clara.","type":"worked-example","props":{"icon":"Mountain","problem":"Julio quiere mostrar, sin palabras, un volcán que duerme, despierta, hace erupción y vuelve a la calma.","steps":[{"text":"**Inicio (8 tiempos):** nivel **bajo**, postura cerrada, quieto; solo respira despacio. Intención: el volcán duerme."},{"text":"**Parte 2 (8 tiempos):** sube **lentamente** al nivel medio, temblando un poco los brazos. Intención: el volcán despierta.","why":"La velocidad lenta y el temblor crean suspenso."},{"text":"**Parte 3 (8 tiempos):** salta al nivel **alto**, brazos que se abren **rápido y con energía fuerte** hacia arriba y en **zigzag**. Intención: la erupción."},{"text":"**Final (8 tiempos):** baja en **trayectoria curva**, con movimientos **suaves**, hasta quedar quieto en nivel bajo. Intención: la lava se enfría y vuelve la calma."}],"answer":"Julio combinó **niveles, velocidad, energía y trayectorias** con una **intención** clara en cada parte, en 4 × 8 = 32 tiempos.","tip":"Empieza y termina siempre con una posición quieta: el público entiende dónde empieza y dónde acaba la historia."},"id":"s03-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.12"],"ambito":"hacer","prompt":"Une cada idea que quieres comunicar con el recurso expresivo que mejor la muestra.","hint":"Piensa en la postura, la energía y la velocidad de cada emoción.","explain":"Cada recurso tiene una intención: la postura cerrada comunica frío o miedo, la energía fuerte enojo o fuerza, la lentitud calma o cansancio.","type":"match","props":{"leftTitle":"Quiero comunicar…","rightTitle":"Recurso","pairs":[{"id":"f","left":"Tengo mucho frío","right":"Postura cerrada y temblorosa"},{"id":"t","left":"Llega una tormenta","right":"Energía fuerte y movimientos rápidos"},{"id":"c","left":"El agua del lago en calma","right":"Movimientos suaves, lentos y curvos"},{"id":"a","left":"¡Ganamos el partido!","right":"Postura abierta, brazos arriba y sonrisa"}]},"id":"s03-ef-2-5"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.4.2","ef:1.4.12"],"ambito":"hacer","prompt":"¡Tu secuencia! **Calentamiento:** muévete por el espacio en trayectoria recta, curva y zigzag (20 s cada una), cambiando de nivel cuando alguien diga \\"¡bajo!\\", \\"¡medio!\\", \\"¡alto!\\". **Parte principal:** crea tu propia secuencia de **4 partes de 8 tiempos** sobre uno de estos temas: \\"La milpa crece\\", \\"Un día de lluvia\\" o \\"El río baja de la montaña\\". Usa al menos 2 niveles, 2 trayectorias y cambios de velocidad. Repítela 3 veces hasta que te salga fluida y muéstrasela a alguien. **Poco espacio:** usa más los niveles que el desplazamiento. **Adaptación:** en silla de ruedas, usa brazos, tronco, cabeza y giros de la silla. **Vuelta a la calma:** estira y respira.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después del calentamiento en el espacio","exercise":{"name":"Trayectorias y niveles","icon":"Route","seconds":60}},{"label":"Después de tu secuencia (3 veces)","exercise":{"name":"Secuencia expresiva de 4 × 8 tiempos","icon":"Sparkles","seconds":90}}]},"id":"s03-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.4.2","ef:1.4.12"],"ambito":"hacer","prompt":"Escribe el **guion de tu secuencia**: el tema, y en cada una de las 4 partes de 8 tiempos, qué **nivel**, **trayectoria**, **velocidad** y **energía** usaste y qué querías **comunicar**.","type":"short-answer","props":{"minWords":40,"placeholder":"Mi tema es… Parte 1: … Parte 2: … Parte 3: … Parte 4: …","model":"Mi tema es \\"El río baja de la montaña\\". Parte 1: nivel alto, de puntillas, movimientos suaves; soy el agua que nace arriba. Parte 2: nivel medio, trayectoria en zigzag y más rápido; el río baja entre piedras. Parte 3: nivel bajo, energía fuerte, brazos que empujan; es una crecida por la lluvia. Parte 4: trayectoria curva, lento y suave hasta quedar quieta; el río llega tranquilo al lago.","rubric":["Tiene un tema claro","Describe 4 partes de 8 tiempos","Usa al menos 2 niveles y 2 trayectorias","Explica la intención de cada parte"]},"id":"s03-ef-2-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.4.2","ef:1.4.12"],"ambito":"hacer","prompt":"Para representar a una persona que avanza con cautela por una ruta estrecha, ¿qué secuencia comunica mejor esa intención?","type":"choice","props":{"options":[{"id":"a","text":"Pasos lentos en línea curva, nivel medio, mirada al frente y energía suave"},{"id":"b","text":"Saltos rápidos sin mirar, con giros amplios y energía fuerte"},{"id":"c","text":"Quedarse inmóvil de espaldas durante toda la secuencia"}],"correct":["a"]},"id":"s03-ef-2-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.4.2"],"prompt":"Te mueves **agachado**, con las rodillas muy dobladas y las manos cerca del suelo. ¿En qué nivel estás?","type":"choice","props":{"options":[{"id":"a","text":"Nivel alto"},{"id":"b","text":"Nivel medio"},{"id":"c","text":"Nivel bajo"}],"correct":["c"]},"id":"s03-ef-2-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.4.2","ef:1.4.12"],"prompt":"Clasifica cada elemento: ¿es una **relación espacio-temporal** o un **recurso expresivo**?","type":"sort","props":{"buckets":[{"id":"e","label":"Espacio-tiempo","icon":"Compass","color":"var(--area-ef)"},{"id":"x","label":"Recurso expresivo","icon":"Smile","color":"var(--c-maiz-strong)"}],"items":[{"id":"y1","text":"Trayectoria en zigzag","bucket":"e"},{"id":"y2","text":"Mirada hacia abajo","bucket":"x"},{"id":"y3","text":"Nivel alto","bucket":"e"},{"id":"y4","text":"Gesto de sorpresa","bucket":"x"},{"id":"y5","text":"Postura encogida","bucket":"x"}]},"id":"s03-ef-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["ef"],"cnb":["ef:1.4.12"],"type":"reflection","props":{"statements":["Marcho y troto siguiendo el pulso de la música","Uso niveles, direcciones y trayectorias","Comunico una idea con gestos, postura, energía y velocidad"],"commitments":["Practicaré mi patrón de 8 tiempos con una canción","Presentaré mi secuencia a mi familia","Observaré cómo se mueven los danzantes en las fiestas de mi comunidad"]},"id":"s03-ef-2-11"}],"kind":"materia","area":"ef","day":5}},{"missionId":"s03","version":"cnb-sexto-76670bcb13e26f66","lesson":{"id":"s03-cnt-2","title":"ADN, genes y la diversidad de la vida","icon":"Dna","minutes":14,"gancho":"En el mercado hay mazorcas amarillas, blancas, moradas y rojas. ¿Son el mismo maíz? ¿Por qué se ven tan distintas?","objetivos":["Explicar la relación entre ADN, genes, cromosomas y diversidad biológica"],"resumen":["Todos los seres vivos usan ADN con el mismo \\"alfabeto\\" químico de cuatro letras. Lo que cambia es el mensaje: genes distintos producen especies distintas.","Cada especie tiene un número fijo de cromosomas (personas 46, maíz 20, perro 78). Tener más cromosomas no significa ser más complejo.","Dentro de una especie hay variación porque cada individuo recibe una mezcla de genes de sus progenitores y porque el ADN puede tener pequeños cambios (mutaciones). El ambiente también influye.","La diversidad protege la vida: si llega una sequía o una plaga, algunas variedades resisten."],"media":{"id":"s03-cnt-2-maices","kind":"image","title":"Los colores del maíz","aspect":"16:9","alt":"Fotografía de mazorcas de maíz amarillo, blanco, morado, rojo y pinto, ordenadas sobre un petate en un mercado de Guatemala.","brief":"Fotografía cenital de mazorcas de maíz de distintos colores (amarillo, blanco, negro o morado, rojo y pinto) sobre un petate, con luz natural. Sin personas identificables ni marcas. Rótulo superpuesto: \\"Una sola especie: Zea mays\\". Opcional: una mano sosteniendo una mazorca abierta para mostrar granos de dos colores. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:2.2.1"],"ambito":"conocer","title":"El mismo alfabeto, mensajes distintos","prompt":"Recuerda: el **ADN** forma los **cromosomas**, y los **genes** son pedazos de ADN con instrucciones. Toca las tarjetas.","media":{"id":"s03-cnt-2-alfabeto","kind":"animation","title":"Cuatro letras, millones de seres","aspect":"16:9","duration":40,"alt":"Animación: las letras A, T, C y G se ordenan en cadenas distintas; cada cadena se convierte en un ser vivo diferente: un hongo, una planta de maíz, un quetzal y una persona.","brief":"Animación 2D de 40 s. Cuatro fichas de colores con las letras A, T, C, G. Se combinan en cadenas de distinto orden (como palabras). Cada cadena \\"florece\\" en un ser vivo: bacteria, hongo, planta de maíz, jaguar, quetzal, persona. Mensaje final en pantalla: \\"Todos usamos el mismo alfabeto. Lo que cambia es el mensaje\\". Narración en español con subtítulos."},"type":"explain","props":{"icon":"Dna","body":"El ADN de **todos** los seres vivos, desde una bacteria hasta un quetzal, está escrito con el mismo alfabeto químico de **cuatro \\"letras\\"** (A, T, C y G).","reveal":[{"icon":"BookOpen","front":"Como las palabras","back":"Con las mismas letras, en distinto orden, escribes \\"amor\\" o \\"Roma\\", \\"saco\\" o \\"cosa\\": palabras distintas. Con las mismas 4 letras del ADN, ordenadas de otra forma, se escriben **genes distintos**."},{"icon":"Layers","front":"Genes distintos, especies distintas","back":"Las diferencias en los genes producen **especies diferentes**: por eso un jaguar no se parece a una iguana."},{"icon":"Users","front":"Parecidos de familia","back":"Especies emparentadas tienen ADN **muy parecido**. Mientras más parecido es el ADN, más cercano es el parentesco."}]},"id":"s03-cnt-2-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.2.1"],"ambito":"conocer","prompt":"Las mazorcas amarillas, blancas, moradas y rojas de la imagen, ¿son de la **misma especie**?","explain":"Sí: todas son **maíz** (_Zea mays_). Sus colores distintos se deben a **diferencias en sus genes**. Hoy verás cómo el ADN produce tanta diversidad.","type":"choice","props":{"options":[{"id":"a","text":"Sí, son maíz, pero con genes un poco distintos","icon":"Wheat"},{"id":"b","text":"No, cada color es una planta diferente, sin relación","icon":"X","feedback":"Se pueden cruzar entre sí y dar mazorcas: son la misma especie."},{"id":"c","text":"Sí, y el color depende solo de la pintura del mercado","icon":"Palette","feedback":"El color viene de los granos mismos, no de pintura."}],"correct":["a"]},"id":"s03-cnt-2-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.2.1"],"ambito":"conocer","title":"Ejemplo: ¿más cromosomas es más complejo?","prompt":"Cada especie tiene un número fijo de cromosomas en sus células. Mira cómo razonar con estos datos.","type":"worked-example","props":{"icon":"Hash","problem":"Las células de las personas tienen **46** cromosomas; las del maíz, **20**; y las del perro, **78**. ¿Significa que el perro es más complejo que las personas?","steps":[{"text":"Ordeno: maíz 20 < personas 46 < perro 78."},{"text":"Si más cromosomas fuera \\"más complejo\\", el perro sería más complejo que las personas. Pero las personas hablan, escriben y construyen ciudades.","why":"Un contraejemplo muestra que la idea no funciona."},{"text":"Lo que importa no es **cuántos** cromosomas hay, sino **qué instrucciones** (genes) llevan y cómo se usan."}],"answer":"**No.** El número de cromosomas es una característica de cada especie, pero **no mide** qué tan complejo es un ser vivo.","tip":"Lo que hace distinta a cada especie es el **mensaje** de sus genes."},"id":"s03-cnt-2-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.2.1"],"ambito":"conocer","prompt":"Un jaguar y una iguana usan el mismo alfabeto de ADN. ¿Por qué son tan diferentes?","hint":"Piensa en las palabras \\"saco\\" y \\"cosa\\": mismas letras, orden distinto.","explain":"Tienen **genes diferentes**: el mismo alfabeto, pero instrucciones distintas.","type":"choice","props":{"options":[{"id":"a","text":"Porque sus genes llevan instrucciones distintas","icon":"Dna"},{"id":"b","text":"Porque la iguana no tiene ADN","icon":"X","feedback":"Todos los seres vivos tienen ADN."},{"id":"c","text":"Porque viven en lugares distintos","icon":"Map","feedback":"El lugar influye, pero lo que hace que sean especies diferentes son sus genes."}],"correct":["a"]},"id":"s03-cnt-2-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.2.1"],"ambito":"conocer","title":"¿Por qué somos distintos dentro de una misma especie?","prompt":"Todas las personas somos de la misma especie, pero nadie es igual a otra persona. Toca las tarjetas.","type":"explain","props":{"icon":"Users","body":"La **variación** dentro de una especie tiene varias causas: unas están en los genes y otra en el ambiente.","reveal":[{"icon":"Copy","front":"Mezcla de genes","back":"En la **reproducción sexual**, cada hijo recibe una mezcla de cromosomas de su madre y de su padre. Cada mezcla es diferente."},{"icon":"Sparkles","front":"Mutaciones","back":"A veces el ADN tiene un **cambio pequeño** al copiarse. La mayoría no se nota, algunos causan problemas y unos pocos resultan útiles."},{"icon":"Sun","front":"El ambiente","back":"Dos plantas con los mismos genes crecen distinto si una recibe más **sol, agua y abono**. Los genes y el ambiente trabajan juntos."},{"icon":"Wheat","front":"Selección de los agricultores","back":"Durante miles de años, los agricultores de Mesoamérica **escogieron** las mejores mazorcas para sembrar. Así se formaron muchas variedades de maíz."}]},"id":"s03-cnt-2-5"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:2.2.1"],"ambito":"conocer","prompt":"Clasifica cada ejemplo: ¿es diversidad **entre especies distintas** o **dentro de una misma especie**?","explain":"Frijol negro y frijol rojo son la misma especie; un jaguar y un venado son especies distintas. Todas las personas son una sola especie.","type":"sort","props":{"buckets":[{"id":"entre","label":"Entre especies distintas","icon":"Layers","color":"var(--area-cnt)"},{"id":"dentro","label":"Dentro de una misma especie","icon":"Users","color":"var(--c-maiz-strong)"}],"items":[{"id":"d1","text":"Maíz amarillo y maíz morado","bucket":"dentro"},{"id":"d2","text":"Un jaguar y un venado","bucket":"entre"},{"id":"d3","text":"Dos hermanas con distinto color de cabello","bucket":"dentro"},{"id":"d4","text":"Un quetzal y una iguana","bucket":"entre"},{"id":"d5","text":"Frijol negro y frijol rojo","bucket":"dentro"},{"id":"d6","text":"Un pino y un encino","bucket":"entre"}]},"id":"s03-cnt-2-6"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:2.2.1"],"ambito":"conocer","prompt":"Doña Teresa siembra **cuatro variedades** de maíz en su terreno. Un año llega una sequía y dos de ellas se secan, pero las otras dos dan cosecha. ¿Qué muestra esto?","explain":"Las variedades tienen genes distintos: algunas **resisten mejor** la sequía. Por eso cuidar la diversidad de semillas protege la alimentación.","type":"choice","props":{"options":[{"id":"a","text":"Que es mejor sembrar una sola variedad","icon":"Minus","feedback":"Si hubiera sembrado solo una de las que se secaron, habría perdido toda la cosecha."},{"id":"b","text":"Que la diversidad de genes ayuda a resistir cambios del ambiente","icon":"ShieldCheck"},{"id":"c","text":"Que la sequía no afecta al maíz","icon":"Sun","feedback":"Sí lo afectó: dos variedades se secaron."}],"correct":["b"]},"id":"s03-cnt-2-7"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:2.2.1"],"ambito":"conocer","prompt":"Integra todo lo aprendido: completa el texto.","explain":"ADN → genes → cromosomas; genes distintos = especies distintas; mezcla de genes y mutaciones = variación dentro de la especie.","type":"fill-blank","props":{"text":"El [[ADN]] guarda las instrucciones de la vida. Sus pedazos con instrucciones se llaman [[genes]], y el ADN enrollado forma los [[cromosomas]]. Las especies son distintas porque tienen genes distintos. Dentro de una especie, cada individuo es diferente por la [[mezcla]] de genes de sus progenitores y por pequeños cambios en el ADN llamados [[mutaciones]].","distractors":["vacuolas","nutrientes"]},"id":"s03-cnt-2-8"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:2.2.1"],"prompt":"¿Por qué hay tanta **diversidad** de seres vivos?","type":"choice","props":{"options":[{"id":"a","text":"Porque cada ser vivo usa un alfabeto de ADN diferente"},{"id":"b","text":"Porque los genes llevan instrucciones distintas en cada especie y varían entre individuos"},{"id":"c","text":"Porque solo algunos seres vivos tienen ADN"}],"correct":["b"]},"id":"s03-cnt-2-9"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:2.2.1"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Una especie con más cromosomas siempre es más compleja.","answer":false,"why":"El perro tiene 78 y las personas 46: el número no mide la complejidad."},{"text":"El maíz blanco y el maíz morado pertenecen a la misma especie.","answer":true},{"text":"El ambiente también influye en cómo crece un ser vivo.","answer":true}]},"id":"s03-cnt-2-10"}],"kind":"materia","area":"cnt","day":3}},{"missionId":"s03","version":"cnb-sexto-9c3fba04cb4d3838","lesson":{"id":"s03-pyd-1","title":"Círculos de calidad: resolver problemas en equipo","icon":"Users","minutes":15,"gancho":"En tu escuela el chorro se queda abierto y el agua se desperdicia. ¿Lo resuelve un cartel que diga \\"cierre el chorro\\", o hay que averiguar primero por qué pasa?","objetivos":["Analizar un problema cercano en un círculo de calidad mediante causas, efectos y PNI"],"resumen":["Un círculo de calidad es un grupo pequeño (de 4 a 8 personas) que se reúne con frecuencia, de forma voluntaria, para identificar un problema, analizar sus causas, proponer soluciones, aplicarlas y evaluarlas.","Roles: quien coordina (dirige la reunión), quien hace de secretaría (anota) y los participantes (todos opinan). Reglas: respeto, turnos para hablar y decisiones con datos.","Árbol de problemas: las raíces son las causas, el tronco es el problema y las ramas son los efectos. Se resuelve atacando las causas.","PNI: se anota lo Positivo, lo Negativo y lo Interesante de una propuesta antes de decidir."],"media":{"id":"s03-pyd-1-circulo","kind":"image","title":"Un círculo de calidad en acción","aspect":"16:9","alt":"Seis estudiantes sentados en círculo alrededor de un papelógrafo con un árbol dibujado: raíces con causas, tronco con el problema y ramas con efectos.","brief":"Ilustración de seis estudiantes de sexto (niñas y niños diversos) sentados en círculo en el corredor de una escuela. En el centro, un papelógrafo con un árbol dibujado a marcador: en las raíces tarjetas amarillas (\\"chorro flojo\\", \\"nadie revisa\\"), en el tronco \\"Se desperdicia el agua\\", en las ramas tarjetas celestes (\\"baño sucio\\", \\"tanque vacío\\"). Una niña coordina con un marcador, un niño anota en un cuaderno (secretaría). Al fondo, el chorro de la pila. Estilo plano, colores cálidos, sin textos adicionales. Dimensiones: 1600x900."},"steps":[{"fase":"explorar","areas":["pyd"],"cnb":["pyd:2.3.2"],"ambito":"conocer","title":"¿Qué es un círculo de calidad?","prompt":"Un **círculo de calidad** es un grupo pequeño que se reúne para **mejorar algo** de su entorno. Toca cada tarjeta.","type":"explain","props":{"icon":"Users","body":"Se llama \\"de calidad\\" porque busca que las cosas **funcionen mejor**, y \\"círculo\\" porque todos se sientan como iguales y todos opinan.","reveal":[{"icon":"Users","front":"¿Quiénes lo forman?","back":"De **4 a 8 personas** que comparten el mismo espacio (un grado, un comité, un taller). Participan **de forma voluntaria**."},{"icon":"Calendar","front":"¿Cómo trabajan?","back":"Se reúnen **con frecuencia** (por ejemplo, cada semana) y siguen pasos: problema → datos → causas → soluciones → aplicar → evaluar."},{"icon":"ClipboardList","front":"Roles","back":"**Coordinación:** dirige la reunión y da la palabra. **Secretaría:** anota ideas y acuerdos. **Participantes:** aportan ideas y datos."},{"icon":"Scale","front":"Reglas","back":"Respeto, **turnos** para hablar, criticar ideas y no personas, y decidir con **datos**, no con suposiciones."}]},"id":"s03-pyd-1-1"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.3.1"],"ambito":"emprender","prompt":"El chorro de la escuela se queda abierto y el agua se desperdicia. ¿Qué conviene hacer **primero**?","explain":"Antes de proponer, hay que **averiguar las causas**: quizá el chorro está flojo, quizá nadie revisa o quizá los pequeños no alcanzan a cerrarlo. Cada causa tiene una solución distinta.","type":"choice","props":{"options":[{"id":"a","text":"Averiguar por qué se queda abierto","icon":"Search"},{"id":"b","text":"Castigar a quien lo dejó abierto","icon":"Gavel","feedback":"Sin saber la causa, podrías castigar a alguien que no tuvo la culpa y el problema seguiría."},{"id":"c","text":"Poner un cartel y ya","icon":"FileText","feedback":"Un cartel puede ayudar, pero si la causa es que el chorro está dañado, no servirá."}],"correct":["a"]},"id":"s03-pyd-1-2"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.3.2"],"prompt":"Ordena los **pasos** que sigue un círculo de calidad.","hint":"No se pueden buscar causas sin datos, ni evaluar algo que aún no se ha aplicado.","explain":"Identificar el problema → reunir datos → analizar causas → proponer y elegir soluciones → aplicar → evaluar.","type":"order","props":{"labels":{"start":"Primero","end":"Al final"},"items":[{"id":"c1","text":"Identificar el problema","icon":"Target"},{"id":"c2","text":"Reunir datos (observar, contar, preguntar)","icon":"ClipboardList"},{"id":"c3","text":"Analizar las causas","icon":"Search"},{"id":"c4","text":"Proponer y elegir soluciones","icon":"Lightbulb"},{"id":"c5","text":"Aplicar la solución","icon":"Hammer"},{"id":"c6","text":"Evaluar si funcionó","icon":"ClipboardCheck"}]},"id":"s03-pyd-1-3"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.3.1"],"ambito":"conocer","title":"Técnica 1: el árbol de problemas","prompt":"Para separar **causas** y **efectos** se dibuja un **árbol**. Toca cada parte.","type":"explain","props":{"icon":"TreeDeciduous","body":"Si solo cortas las ramas (efectos), el árbol vuelve a crecer. Para resolver un problema hay que atender sus **raíces** (causas).","reveal":[{"icon":"Sprout","front":"Raíces = causas","back":"¿**Por qué** pasa? Ejemplo: no hay basureros; la refacción viene en bolsas plásticas."},{"icon":"TreePine","front":"Tronco = problema","back":"Lo que queremos resolver, en una oración: \\"Hay basura en el patio\\"."},{"icon":"Leaf","front":"Ramas = efectos","back":"¿**Qué provoca**? Ejemplo: moscas, mal olor, drenajes tapados cuando llueve."}]},"id":"s03-pyd-1-4"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.3.1"],"prompt":"Problema: **\\"Hay basura en el patio de la escuela\\"**. ¿Cada tarjeta es una **causa** (raíz) o un **efecto** (rama)?","hint":"Causa = por qué pasa (viene antes). Efecto = qué provoca (viene después).","explain":"Las causas explican por qué hay basura; los efectos son lo que la basura provoca. Las soluciones deben atacar las causas.","type":"sort","props":{"buckets":[{"id":"cau","label":"Causa (raíz)","icon":"Sprout","color":"var(--c-maiz-strong)"},{"id":"efe","label":"Efecto (rama)","icon":"Leaf","color":"var(--area-pyd)"}],"items":[{"id":"b1","text":"Solo hay un basurero para toda la escuela","bucket":"cau"},{"id":"b2","text":"Hay moscas cerca de la tienda escolar","bucket":"efe"},{"id":"b3","text":"La refacción se vende en bolsas plásticas","bucket":"cau"},{"id":"b4","text":"Los drenajes se tapan cuando llueve","bucket":"efe"},{"id":"b5","text":"Nadie tiene turno para recoger la basura","bucket":"cau"},{"id":"b6","text":"El patio huele mal","bucket":"efe"}]},"id":"s03-pyd-1-5"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.3.1"],"ambito":"conocer","title":"Técnica 2: el análisis PNI","prompt":"Cuando hay una **propuesta** de solución, antes de decidir se analiza con **PNI**. Toca cada letra.","type":"explain","props":{"icon":"ListChecks","body":"El PNI evita decir \\"¡sí!\\" o \\"¡no!\\" demasiado rápido. Obliga a mirar la propuesta **por todos lados**.","reveal":[{"icon":"ThumbsUp","front":"P = Positivo","back":"¿Qué tiene de **bueno** la propuesta? ¿A quién beneficia?"},{"icon":"X","front":"N = Negativo","back":"¿Qué **problemas o riesgos** trae? ¿A quién podría afectar?"},{"icon":"Lightbulb","front":"I = Interesante","back":"¿Qué **preguntas o ideas nuevas** despierta? Lo que no es ni bueno ni malo, pero vale la pena investigar."}]},"id":"s03-pyd-1-6"},{"fase":"construir","areas":["pyd"],"cnb":["pyd:2.3.1","pyd:2.3.2"],"ambito":"hacer","title":"Ejemplo resuelto: un PNI en el círculo de calidad","prompt":"El círculo de calidad de sexto analiza una propuesta de la comunidad. Mira cómo hace su PNI.","type":"worked-example","props":{"icon":"ClipboardList","problem":"Propuesta: **\\"Cerrar la calle del mercado a los carros los domingos para que la gente camine segura.\\"**","steps":[{"text":"**P (positivo):** menos accidentes; las familias caminan tranquilas; más espacio para los puestos."},{"text":"**N (negativo):** los que traen carga en pick-up tendrán que descargar más lejos; puede haber tráfico en otras calles."},{"text":"**I (interesante):** ¿cuántos accidentes hubo el año pasado? ¿Dónde podrían estacionarse los pick-ups? ¿Venderán más los comerciantes?","why":"Lo interesante se convierte en preguntas para reunir más datos."},{"text":"**Decisión del círculo:** apoyar la propuesta, pero con un **lugar de descarga** cerca para los comerciantes."}],"answer":"Con el PNI, el círculo **mejoró** la propuesta: mantuvo lo positivo y buscó cómo reducir lo negativo.","tip":"Positivo → Negativo → Interesante → decidir (y mejorar la propuesta)."},"id":"s03-pyd-1-7"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:2.3.1"],"ambito":"hacer","prompt":"Ahora tú. Propuesta: **\\"Que sexto grado administre una tienda de refacción saludable en la escuela.\\"** Clasifica cada idea en P, N o I.","explain":"P: lo bueno (alimentación sana, ganancias). N: los riesgos (tiempo, dinero). I: preguntas nuevas para investigar.","type":"sort","props":{"buckets":[{"id":"p","label":"P · Positivo","icon":"ThumbsUp","color":"var(--c-ok)"},{"id":"n","label":"N · Negativo","icon":"X","color":"var(--c-bad)"},{"id":"i","label":"I · Interesante","icon":"Lightbulb","color":"var(--c-maiz-strong)"}],"items":[{"id":"r1","text":"Los estudiantes comerían más fruta y menos golosinas","bucket":"p"},{"id":"r2","text":"Atender la tienda podría quitar tiempo del recreo a los encargados","bucket":"n"},{"id":"r3","text":"¿Qué frutas de temporada serían más baratas cada mes?","bucket":"i"},{"id":"r4","text":"Las ganancias podrían usarse para la excursión del grado","bucket":"p"},{"id":"r5","text":"Si no se vende la fruta, se puede echar a perder","bucket":"n"},{"id":"r6","text":"¿Podrían las familias de la aldea vender sus frutas a la tienda?","bucket":"i"}]},"id":"s03-pyd-1-8"},{"fase":"aplicar","areas":["pyd"],"cnb":["pyd:2.3.1"],"ambito":"emprender","prompt":"Análisis de caso: el círculo de calidad descubrió que el chorro de la escuela se queda abierto porque **la llave está floja y no cierra bien**. ¿Qué solución ataca **la causa**?","explain":"La causa es una llave dañada: la solución que ataca la raíz es **repararla o cambiarla**. Los carteles o regaños no arreglan una llave floja.","type":"choice","props":{"options":[{"id":"a","text":"Pedir a la dirección y a un padre de familia que cambien la llave del chorro"},{"id":"b","text":"Regañar a todos los estudiantes en la formación","feedback":"Los estudiantes no tienen la culpa de que la llave esté floja."},{"id":"c","text":"Poner un cartel más grande","feedback":"Aunque todos quieran cerrarlo, la llave dañada no cierra bien."}],"correct":["a"]},"id":"s03-pyd-1-9"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:2.3.2"],"prompt":"¿Qué es un **círculo de calidad**?","type":"choice","props":{"options":[{"id":"a","text":"Un grupo pequeño que se reúne con frecuencia para analizar problemas y proponer soluciones"},{"id":"b","text":"Un juego de pelota en círculo"},{"id":"c","text":"Una tienda que vende productos caros"}],"correct":["a"]},"id":"s03-pyd-1-10"},{"fase":"comprobar","areas":["pyd"],"cnb":["pyd:2.3.1","pyd:2.3.2"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"En un análisis PNI, la I significa \\"Interesante\\".","answer":true},{"text":"En el árbol de problemas, las raíces representan los efectos.","answer":false,"why":"Las raíces son las causas; las ramas son los efectos."},{"text":"En un círculo de calidad, la secretaría anota las ideas y los acuerdos.","answer":true},{"text":"Un círculo de calidad debe tener al menos 30 personas.","answer":false,"why":"Es un grupo pequeño, de 4 a 8 personas."}]},"id":"s03-pyd-1-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["pyd"],"cnb":["pyd:2.3.1","pyd:2.3.2"],"type":"reflection","props":{"statements":["Explico qué es un círculo de calidad y sus pasos","Separo causas y efectos con el árbol de problemas","Evalúo una propuesta con PNI"],"commitments":["Propondré formar un círculo de calidad en mi grado","Antes de decir sí o no a una idea, haré su PNI"]},"id":"s03-pyd-1-12"}],"kind":"materia","area":"pyd","day":3}},{"missionId":"s03","version":"cnb-sexto-12e45f5561f1214d","lesson":{"id":"s03-l3-2","title":"My impressions in three sentences","icon":"Sparkles","minutes":15,"gancho":"\\"I got up early. I saw the sun shining, and I thought: what a beautiful morning! I am happy.\\" Con solo tres oraciones, ¿ya sabes cómo se sintió quien lo escribió?","objetivos":["Narrar en tres oraciones una experiencia, una observación y una impresión personal"],"resumen":["Una impresión es lo que sientes o piensas de algo que viviste.","Receta de tres oraciones: 1) What I did: I went… / I got up… 2) What I saw or heard: I saw… / I heard… 3) How I felt: I felt happy. / I thought it was beautiful!","Sentimientos: happy (feliz), excited (emocionado), tired (cansado), surprised (sorprendido), calm (tranquilo).","Impresiones: beautiful (hermoso), amazing (increíble), fun (divertido), delicious (delicioso), noisy (ruidoso)."],"media":{"id":"s03-l3-2-morning","kind":"image","title":"A beautiful morning","aspect":"16:9","alt":"Una niña abre la ventana de su casa al amanecer y sonríe al ver el sol salir detrás de un volcán.","brief":"Ilustración cálida al amanecer: una niña de 11-12 años abre la ventana de madera de su casa en un pueblo del altiplano y sonríe; afuera, el sol sale detrás de un volcán y hay milpa y neblina suave. Tres globitos pequeños con íconos (un despertador, un ojo con el sol, un corazón) que representan las tres oraciones: lo que hice, lo que vi, lo que sentí. Sin texto. Dimensiones: 1600x900."},"steps":[{"fase":"explorar","areas":["l3"],"cnb":["l3:1.3.3"],"ambito":"conocer","title":"The three-sentence recipe","prompt":"Para contar una impresión en inglés, usa esta receta de **tres oraciones**. Toca cada paso.","type":"explain","props":{"icon":"ListOrdered","body":"Usa el **pasado** que aprendiste el martes (went, saw, ate, was). Para \\"sentí\\" se dice **I felt** (pasado de feel).","reveal":[{"icon":"Footprints","front":"1. What I did","back":"Lo que hiciste: _I **went** to the fair._ · _I **got up** early._ · _I **visited** my aunt._"},{"icon":"Eye","front":"2. What I saw or heard","back":"Lo que viste u oíste: _I **saw** a big Ferris wheel._ · _I **heard** the marimba._"},{"icon":"Heart","front":"3. How I felt","back":"Tu impresión: _I **felt** happy._ · _I **was** excited._ · _I **thought** it was amazing!_"}]},"id":"s03-l3-2-1"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.3.3"],"ambito":"conocer","prompt":"Lee: _\\"I got up early. I saw the sun shining, and I thought: what a beautiful morning! I am happy.\\"_ ¿Cómo se siente quien lo escribió?","explain":"**Happy** = feliz, y **beautiful** = hermoso. Con tres oraciones contó qué hizo, qué vio y cómo se sintió. Hoy aprenderás a escribir así tus propias impresiones.","type":"choice","props":{"options":[{"id":"a","text":"Feliz","icon":"Smile"},{"id":"b","text":"Enojado","icon":"Frown","feedback":"Busca la palabra \\"happy\\" al final: significa feliz."},{"id":"c","text":"Aburrido","icon":"Meh","feedback":"Dice \\"what a beautiful morning!\\" y \\"I am happy\\": no está aburrido."}],"correct":["a"]},"id":"s03-l3-2-2"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.3.3"],"ambito":"conocer","title":"Feelings and impressions","prompt":"Escucha y repite cada adjetivo. Voltea la tarjeta para ver su significado y un ejemplo.","media":{"id":"s03-l3-2-adjectives","kind":"audio","title":"Feelings and impressions","duration":35,"alt":"Una voz en inglés dice adjetivos de sentimientos e impresiones con un ejemplo cada uno.","brief":"Audio de 35 s. Voz adulta, inglés claro y expresivo (la entonación refleja cada emoción), sin música. Texto exacto, con 1 s de pausa: \\"happy – I felt happy.\\" \\"excited – I was excited.\\" \\"tired – I was tired.\\" \\"surprised – I was surprised.\\" \\"beautiful – It was beautiful.\\" \\"amazing – It was amazing!\\" \\"delicious – It was delicious.\\" \\"fun – It was fun.\\" \\"calm – I felt calm.\\""},"type":"flashcards","props":{"cards":[{"icon":"Smile","front":"happy","back":"feliz · _I felt happy._"},{"icon":"PartyPopper","front":"excited","back":"emocionado/a · _I was excited._"},{"icon":"Moon","front":"tired","back":"cansado/a · _I was tired._"},{"icon":"Sparkles","front":"surprised","back":"sorprendido/a · _I was surprised._"},{"icon":"Flower","front":"beautiful","back":"hermoso/a · _It was beautiful._"},{"icon":"Star","front":"amazing","back":"increíble · _It was amazing!_"},{"icon":"Utensils","front":"delicious","back":"delicioso/a · _It was delicious._"},{"icon":"PartyPopper","front":"fun","back":"divertido/a · _It was fun!_"},{"icon":"Leaf","front":"calm","back":"tranquilo/a · _I felt calm._"}]},"id":"s03-l3-2-3"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.3.3"],"ambito":"hacer","title":"Worked example","prompt":"Mira cómo Keila escribe su impresión de un día en la playa de Livingston, Izabal.","type":"worked-example","props":{"icon":"Waves","problem":"Keila fue a la playa con su familia, vio muchos pelícanos y se sintió muy emocionada. ¿Cómo lo cuenta en tres oraciones?","steps":[{"text":"Oración 1 (what I did): **I went to the beach with my family.**","why":"Go es irregular: went."},{"text":"Oración 2 (what I saw): **I saw many pelicans.**","why":"See es irregular: saw. Pelican + s = pelicans."},{"text":"Oración 3 (how I felt): **I was very excited!**","why":"\\"Very\\" (muy) hace más fuerte al adjetivo."}],"answer":"**I went to the beach with my family. I saw many pelicans. I was very excited!**","tip":"Hice → vi → sentí. Tres oraciones cortas y claras bastan."},"id":"s03-l3-2-4"},{"fase":"construir","areas":["l3"],"cnb":["l3:1.3.3"],"ambito":"hacer","prompt":"Ahora tú, con ayuda: ¿qué parte de la receta es cada oración?","hint":"Busca el verbo: went, visited → hice. Saw, heard → vi u oí. Felt, was + adjetivo → sentí.","explain":"Did: I went to the fair / I visited my cousins. Saw or heard: I saw fireworks / I heard the marimba. Felt: I felt surprised / It was fun!","type":"sort","props":{"buckets":[{"id":"d","label":"1. What I did","icon":"Footprints"},{"id":"s","label":"2. What I saw or heard","icon":"Eye"},{"id":"f","label":"3. How I felt","icon":"Heart"}],"items":[{"id":"x1","text":"I went to the fair.","bucket":"d"},{"id":"x2","text":"I saw fireworks.","bucket":"s"},{"id":"x3","text":"I felt surprised.","bucket":"f"},{"id":"x4","text":"I visited my cousins.","bucket":"d"},{"id":"x5","text":"I heard the marimba.","bucket":"s"},{"id":"x6","text":"It was fun!","bucket":"f","feedback":"\\"It was fun\\" es tu impresión: dice cómo te pareció."}]},"id":"s03-l3-2-5"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.3.3"],"ambito":"hacer","prompt":"Pablo caminó 3 horas para subir a un volcán. Al llegar arriba, ¿qué adjetivo describe mejor **cómo estaba su cuerpo**?","explain":"Después de caminar tanto, Pablo estaba **tired** (cansado). ¡Quizás también happy por la vista!","type":"choice","props":{"options":[{"id":"a","text":"I was tired."},{"id":"b","text":"It was delicious.","feedback":"\\"Delicious\\" describe comida, no cómo se siente tu cuerpo."},{"id":"c","text":"I was noisy.","feedback":"\\"Noisy\\" es ruidoso: describe un lugar con mucho ruido."}],"correct":["a"]},"id":"s03-l3-2-6"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.3.3"],"ambito":"hacer","prompt":"Ordena las tres oraciones de Andrea según la receta: hice → vi → sentí.","explain":"Primero lo que hizo (went), luego lo que vio (saw) y al final su impresión (was amazing).","type":"order","props":{"labels":{"start":"1","end":"3"},"items":[{"id":"o1","text":"I went to the Sumpango kite festival."},{"id":"o2","text":"I saw giant kites of many colors."},{"id":"o3","text":"It was amazing!"}]},"id":"s03-l3-2-7"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.3.3"],"ambito":"hacer","title":"Reading","prompt":"Lee las impresiones de dos estudiantes y responde. Pistas: _smell_ = olor, _bread_ = pan, _loud_ = fuerte (sonido).","type":"reading","props":{"genre":"Short texts","heading":"Our weekend","passage":"Luis: Last Saturday I helped my dad at the bakery. I saw the bread come out of the oven. The smell was delicious, and I felt proud.\\n\\nMarta: On Sunday I went to a concert in the park. I heard a big marimba and a drum. The music was loud, but it was fun!","questions":[{"q":"What did Luis do?","options":[{"id":"a","text":"He helped his dad at the bakery."},{"id":"b","text":"He went to a concert."},{"id":"c","text":"He played football."}],"correct":"a"},{"q":"What did Marta hear?","options":[{"id":"a","text":"A marimba and a drum"},{"id":"b","text":"A bird and the rain"},{"id":"c","text":"Her dad"}],"correct":"a"},{"q":"¿Cómo se sintió Luis? (Pista: _proud_ = orgulloso)","options":[{"id":"a","text":"Orgulloso"},{"id":"b","text":"Aburrido"},{"id":"c","text":"Asustado"}],"correct":"a","why":"\\"I felt proud\\": se sintió orgulloso de ayudar a su papá."}]},"id":"s03-l3-2-8"},{"fase":"aplicar","areas":["l3"],"cnb":["l3:1.3.3"],"ambito":"hacer","prompt":"Your turn! Piensa en algo que viviste esta semana. Escribe **tres oraciones en inglés**: qué hiciste, qué viste u oíste, y cómo te sentiste.","type":"short-answer","props":{"minWords":12,"placeholder":"I went… I saw… I felt…","model":"On Wednesday I walked to school with my sister. I saw a rainbow over the mountains. I felt very happy!","rubric":["Escribí tres oraciones en inglés","La primera dice qué hice, con un verbo en pasado","La segunda dice qué vi u oí (saw / heard)","La tercera dice cómo me sentí con un adjetivo (happy, excited, tired…)"]},"id":"s03-l3-2-9"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:1.3.3"],"prompt":"Boleto de salida: completa la narración de Ana. (Fui al río. Vi muchos peces. Me sentí tranquila.)","type":"fill-blank","props":{"text":"I [[went]] to the river. I [[saw]] many fish. I [[felt]] calm.","distractors":["go","see","feel"]},"id":"s03-l3-2-10"},{"fase":"comprobar","areas":["l3"],"cnb":["l3:1.3.3"],"prompt":"¿Cuál oración expresa una **impresión** (cómo se sintió o qué le pareció)?","type":"choice","props":{"options":[{"id":"a","text":"I got up at six."},{"id":"b","text":"I went to the park."},{"id":"c","text":"It was a beautiful day!"}],"correct":["c"]},"id":"s03-l3-2-11"},{"fase":"reflexionar","areas":["l3"],"cnb":[],"ambito":"ser","prompt":"How do you feel? ¿Cómo te fue esta semana?","type":"reflection","props":{"statements":["Uso el pasado de verbos regulares (-ed)","Recuerdo pasados irregulares: went, saw, ate, had, was","Cuento una experiencia en tres oraciones: hice, vi, sentí"],"commitments":["Cada noche diré en inglés una cosa que hice ese día","Escribiré mis tres oraciones del fin de semana","Aprenderé dos verbos irregulares nuevos"]},"id":"s03-l3-2-12"}],"kind":"materia","area":"l3","day":4}},{"missionId":"s03","version":"cnb-sexto-425c84e15f809cd1","lesson":{"id":"s03-fc-2","title":"Pensar críticamente ante la discriminación","icon":"Search","minutes":15,"gancho":"\\"Las niñas no saben jugar fútbol.\\" \\"Los de ese pueblo son haraganes.\\" ¿Has escuchado frases así? ¿Son verdad?","objetivos":["Responder críticamente y con respeto ante argumentos que justifican la discriminación"],"resumen":["Estereotipo: idea simplificada sobre un grupo (\\"todos los… son…\\"). Prejuicio: juzgar a alguien antes de conocerlo, por su grupo. Discriminación: tratar peor a alguien por su pueblo, idioma, sexo, religión, discapacidad o pobreza.","Machismo: creer que los hombres valen más que las mujeres. Sexismo: dar distinto trato u oportunidades por ser hombre o mujer. Racismo y discriminación étnica: despreciar a alguien por su pueblo, color de piel o cultura.","Un argumento discriminatorio generaliza, juzga por el grupo y no por la persona, y convierte una diferencia en inferioridad. Se responde pidiendo pruebas, dando contraejemplos y recordando la igualdad de derechos.","La Constitución de Guatemala (artículo 4) dice que todos los seres humanos son libres e iguales en dignidad y derechos. La discriminación es un delito en el Código Penal."],"media":{"id":"s03-fc-2-lupa","kind":"animation","title":"La lupa del pensamiento crítico","aspect":"16:9","duration":45,"alt":"Una frase discriminatoria aparece en un globo de diálogo; una lupa la examina y señala la generalización, luego aparece una respuesta respetuosa con un contraejemplo.","brief":"Animación 2D de 45 s. Aparece un globo de diálogo: \\"Todas las niñas son malas para las matemáticas\\". Una lupa se acerca y resalta en amarillo la palabra \\"Todas\\" con la etiqueta \\"generalización\\". Luego aparecen tres ejemplos de niñas resolviendo problemas, construyendo y programando: \\"contraejemplos\\". Finalmente un nuevo globo: \\"Cada persona es distinta; las capacidades no dependen del sexo\\". Narración en español, subtítulos. Colores suaves, personajes diversos."},"steps":[{"fase":"explorar","areas":["fc"],"cnb":["fc:1.2.3"],"ambito":"conocer","title":"De la idea al daño","prompt":"La discriminación casi siempre empieza con una **idea equivocada** en la cabeza. Mira cómo avanza. Toca cada tarjeta en orden.","type":"explain","props":{"icon":"Layers","body":"Si frenamos la idea a tiempo, frenamos el daño. Por eso importa **pensar críticamente**.","reveal":[{"icon":"Brain","front":"1. Estereotipo","back":"Una idea **simplificada** sobre un grupo: \\"Todos los de la capital son…\\", \\"Las mujeres son…\\". Borra las diferencias entre personas."},{"icon":"Eye","front":"2. Prejuicio","back":"**Juzgar** a alguien antes de conocerlo, solo por el grupo al que pertenece. \\"No la invito: seguro no sabe.\\""},{"icon":"X","front":"3. Discriminación","back":"**Tratar peor** a alguien por su pueblo, idioma, sexo, religión, discapacidad o pobreza: excluirlo, burlarse, negarle una oportunidad."}]},"id":"s03-fc-2-1"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.3"],"ambito":"conocer","prompt":"Un compañero dice: **\\"Las niñas no saben jugar fútbol.\\"** ¿Qué le responderías?","explain":"Muchas niñas juegan fútbol muy bien, y en Guatemala hay selecciones y ligas femeninas. La frase **generaliza**: habla de \\"las niñas\\" como si todas fueran iguales. Hoy aprenderás a detectar y responder frases así.","type":"choice","props":{"options":[{"id":"a","text":"Que eso no es cierto: jugar bien depende de practicar, no de ser niña o niño","icon":"Scale"},{"id":"b","text":"Que tiene razón, siempre ha sido así","icon":"ThumbsUp","feedback":"Que algo \\"siempre se haya dicho\\" no lo hace verdad. Piensa en niñas que conoces que juegan bien."}],"correct":["a"]},"id":"s03-fc-2-2"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.3"],"ambito":"conocer","title":"Formas de discriminación que hay que nombrar","prompt":"Poner nombre a las cosas ayuda a reconocerlas. Toca cada tarjeta.","type":"explain","props":{"icon":"Search","body":"Todas estas formas van contra la **igualdad**. La Constitución de Guatemala, en su **artículo 4**, dice que **todos los seres humanos son libres e iguales en dignidad y derechos**, y que hombres y mujeres tienen iguales oportunidades y responsabilidades.","reveal":[{"icon":"User","front":"Machismo","back":"Creer que los **hombres valen más** que las mujeres o que deben mandar sobre ellas. \\"Eso es cosa de hombres.\\""},{"icon":"Users","front":"Sexismo","back":"Dar **distinto trato u oportunidades** a alguien por ser hombre o mujer. \\"Las niñas limpian, los niños cargan.\\""},{"icon":"Hand","front":"Racismo","back":"Creer que hay personas **superiores o inferiores** por su color de piel u origen, y tratarlas en consecuencia."},{"icon":"Languages","front":"Discriminación étnica","back":"Despreciar a alguien por su **pueblo, idioma o traje**. Por ejemplo, burlarse de quien usa güipil o habla un idioma maya."}]},"id":"s03-fc-2-3"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.3"],"prompt":"Clasifica cada frase o acción según el tipo de discriminación.","hint":"¿Se desprecia a alguien por ser mujer (machismo o sexismo) o por su pueblo, color o idioma (racismo o discriminación étnica)?","explain":"Machismo y sexismo discriminan por el sexo; racismo y discriminación étnica, por el origen, el color de piel, el idioma o la cultura.","type":"sort","props":{"buckets":[{"id":"sex","label":"Machismo o sexismo","icon":"Users","color":"var(--area-fc)"},{"id":"rac","label":"Racismo o discriminación étnica","icon":"Languages","color":"var(--c-maiz-strong)"}],"items":[{"id":"f1","text":"\\"Las mujeres no deberían manejar camionetas.\\"","bucket":"sex"},{"id":"f2","text":"No atender a una señora en la tienda porque habla mam","bucket":"rac"},{"id":"f3","text":"\\"En esta casa los hombres no lavan platos.\\"","bucket":"sex"},{"id":"f4","text":"Poner apodos a un compañero por su color de piel","bucket":"rac"},{"id":"f5","text":"Pagarle menos a una mujer por hacer el mismo trabajo que un hombre","bucket":"sex","feedback":"Es sexismo: el trabajo es el mismo, pero se paga distinto solo por ser mujer."},{"id":"f6","text":"Decir que el traje maya \\"se ve feo\\" y pedir que no lo usen en la escuela","bucket":"rac"}]},"id":"s03-fc-2-4"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.3"],"ambito":"hacer","title":"Ejemplo resuelto: desarmar un argumento discriminatorio","prompt":"Algunas personas intentan **justificar** la discriminación con \\"argumentos\\". Mira cómo analizarlos con tres preguntas.","type":"worked-example","props":{"icon":"Search","problem":"En una reunión alguien dice: **\\"No elijamos a una mujer como presidenta del comité, porque las mujeres son muy sentimentales para mandar.\\"**","steps":[{"text":"**¿Generaliza?** Sí: habla de \\"las mujeres\\" como si todas fueran iguales.","why":"Las palabras \\"todos\\", \\"todas\\", \\"siempre\\", \\"nunca\\" son una alerta."},{"text":"**¿Juzga por el grupo y no por la persona?** Sí: no revisa si esa candidata en concreto tiene experiencia, ideas o honestidad."},{"text":"**¿Convierte una diferencia en inferioridad?** Sí: supone que sentir emociones impide dirigir. Todas las personas, hombres y mujeres, sienten emociones."},{"text":"**Respondo con argumentos:** \\"Hay mujeres que dirigen muy bien comités, municipalidades y empresas. Elijamos por las propuestas y la honestidad de cada candidato, no por su sexo.\\""}],"answer":"El argumento es **machista**: generaliza, juzga por el grupo y convierte una diferencia en inferioridad. Se responde con **contraejemplos** y con el principio de **igualdad**.","tip":"Tres preguntas: ¿generaliza? ¿juzga por el grupo? ¿convierte la diferencia en inferioridad?"},"id":"s03-fc-2-5"},{"fase":"construir","areas":["fc"],"cnb":["fc:1.2.3"],"prompt":"Toca las **palabras que generalizan** en estas frases. Son la primera alerta de un estereotipo.","hint":"Busca palabras que hablan de un grupo entero o de \\"siempre/nunca\\".","explain":"\\"Todos\\", \\"todas\\", \\"siempre\\", \\"nunca\\" y \\"ninguno\\" convierten a muchas personas distintas en una sola idea. Por eso son una alerta.","type":"highlight","props":{"target":"palabras que generalizan","text":"{Todos} los jóvenes son irresponsables. Las niñas {nunca} entienden de computadoras. {Ninguno} de esa aldea sabe leer bien. En la ciudad la gente {siempre} es egoísta."},"id":"s03-fc-2-6"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.3"],"ambito":"convivir","prompt":"¿Qué harías tú?","type":"dilemma","props":{"scene":{"icon":"MessageCircle","text":"En la cancha, **Kevin** dice: \\"Las niñas no pueden ser capitanas del equipo porque no saben mandar\\". Varias niñas quieren postularse y se quedan calladas."},"options":[{"id":"a","icon":"ThumbsUp","text":"Darle la razón a Kevin para no pelear","consequence":"Las niñas se quedan fuera y se repite una idea falsa y machista.","values":["Machismo","Silencio"],"constructive":false},{"id":"b","icon":"Scale","text":"Preguntarle a Kevin: \\"¿Por qué lo dices? ¿Conoces a todas las niñas?\\" y proponer elegir por quién organiza mejor al equipo","consequence":"Kevin no tiene pruebas. El grupo acuerda elegir por capacidades y una niña es elegida capitana.","values":["Pensamiento crítico","Equidad"],"constructive":true},{"id":"c","icon":"Users","text":"Proponer que la capitanía rote entre niñas y niños cada semana","consequence":"Todas y todos practican el liderazgo. Kevin descubre que sus compañeras organizan muy bien.","values":["Inclusión","Igualdad de oportunidades"],"constructive":true}]},"id":"s03-fc-2-7"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.3"],"prompt":"Alguien dice: **\\"Si hablas un idioma maya, te va a costar aprender inglés.\\"** ¿Cuál es la respuesta **más crítica y respetuosa**?","explain":"La frase no tiene pruebas: hablar varios idiomas **no** es un obstáculo; muchas personas bilingües aprenden un tercer idioma con facilidad. Pedir pruebas y dar contraejemplos es pensar críticamente.","type":"choice","props":{"options":[{"id":"a","text":"\\"¿En qué te basas? Conozco personas que hablan k’iche’, español e inglés. Saber varios idiomas ayuda a aprender otro.\\""},{"id":"b","text":"\\"Tienes razón, mejor que dejen de hablar su idioma.\\"","feedback":"Eso sería aceptar un prejuicio y perder una riqueza. No hay pruebas de lo que dice la frase."},{"id":"c","text":"\\"¡Qué tonto eres!\\"","feedback":"Insultar no convence y también es falta de respeto. Mejor responde con argumentos."}],"correct":["a"]},"id":"s03-fc-2-8"},{"fase":"aplicar","areas":["fc"],"cnb":["fc:1.2.3","fc:2.1.1"],"ambito":"conocer","prompt":"Lee y responde. Este texto muestra qué dicen las leyes y los Acuerdos de Paz sobre la discriminación.","type":"reading","props":{"genre":"Texto informativo","heading":"La igualdad también está en la ley","passage":"La **Constitución Política de la República de Guatemala**, en su **artículo 4**, dice que en Guatemala todos los seres humanos son libres e iguales en dignidad y derechos, y que el hombre y la mujer tienen iguales oportunidades y responsabilidades.\\n\\nEn **1995** se firmó el **Acuerdo sobre Identidad y Derechos de los Pueblos Indígenas**, uno de los Acuerdos de Paz. Ese acuerdo reconoce que Guatemala es una nación multiétnica, pluricultural y multilingüe, y pide eliminar la discriminación contra los pueblos indígenas. Además, reconoce que las **mujeres indígenas** han sufrido una **doble discriminación**: por ser mujeres y por ser indígenas.\\n\\nHoy, en Guatemala, la discriminación es un **delito** en el Código Penal. Pero las leyes no bastan: la igualdad también se construye en el aula, en la cancha y en la casa, cada vez que alguien se atreve a decir \\"eso no es justo\\".","questions":[{"q":"¿Qué dice el artículo 4 de la Constitución?","options":[{"id":"a","text":"Que todos los seres humanos son libres e iguales en dignidad y derechos"},{"id":"b","text":"Que solo algunas personas tienen derechos"},{"id":"c","text":"Que los hombres tienen más oportunidades que las mujeres"}],"correct":"a"},{"q":"¿Por qué el Acuerdo habla de \\"doble discriminación\\" de las mujeres indígenas?","options":[{"id":"a","text":"Porque pueden ser discriminadas por ser mujeres y también por ser indígenas"},{"id":"b","text":"Porque tienen dos nombres"},{"id":"c","text":"Porque hablan dos idiomas"}],"correct":"a"},{"q":"Según el último párrafo, ¿qué más hace falta además de las leyes?","options":[{"id":"a","text":"Que las personas practiquen la igualdad en la vida diaria y se atrevan a señalar lo injusto"},{"id":"b","text":"Nada, las leyes lo resuelven todo"},{"id":"c","text":"Esperar a ser adultos"}],"correct":"a","why":"La igualdad se construye con leyes y también con actitudes de cada día."}]},"id":"s03-fc-2-9"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.2.3"],"prompt":"\\"Mi hermana no puede estudiar mecánica porque es mujer.\\" Esta frase es un ejemplo de…","type":"choice","props":{"options":[{"id":"a","text":"Sexismo o machismo"},{"id":"b","text":"Tolerancia"},{"id":"c","text":"Solidaridad"}],"correct":["a"]},"id":"s03-fc-2-10"},{"fase":"comprobar","areas":["fc"],"cnb":["fc:1.2.3"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Un prejuicio es juzgar a alguien antes de conocerlo, solo por su grupo.","answer":true},{"text":"Las palabras \\"todos\\" y \\"nunca\\" pueden ser una alerta de estereotipo.","answer":true},{"text":"Burlarse del traje o del idioma de alguien es discriminación étnica.","answer":true},{"text":"Si una idea se ha repetido por muchos años, entonces es verdad.","answer":false,"why":"Que algo se repita no lo hace cierto: hay que pedir pruebas."}]},"id":"s03-fc-2-11"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["fc"],"cnb":["fc:1.2.3","fc:2.1.1"],"type":"reflection","props":{"statements":["Nombro los cuatro pueblos y los 25 idiomas de Guatemala","Distingo estereotipo, prejuicio y discriminación","Respondo con argumentos a una frase discriminatoria"],"commitments":["Preguntaré en casa qué idiomas hablaban mis abuelos","Cuando escuche \\"todos los… son…\\", preguntaré en qué se basa","Invitaré a participar a alguien que suele quedar excluido"]},"id":"s03-fc-2-12"}],"kind":"materia","area":"fc","day":5}},{"missionId":"s03","version":"cnb-sexto-5051bf2c98847d9e","lesson":{"id":"s03-ef-2","title":"Mi cuerpo en el espacio: direcciones, niveles y expresión","icon":"PersonStanding","minutes":15,"gancho":"Sin decir una palabra, ¿podrías mostrar con tu cuerpo que tienes miedo, que estás feliz o que eres un volcán a punto de despertar?","objetivos":["Crear una secuencia expresiva usando direcciones, niveles, trayectorias, velocidad e intención"],"resumen":["Relaciones espacio-temporales: el cuerpo se mueve en direcciones (adelante, atrás, a los lados, arriba, abajo), niveles (alto, medio, bajo) y trayectorias (recta, curva, zigzag), a distintas velocidades (rápido, lento) y duraciones.","Recursos expresivos: el gesto (cara y manos), la mirada, la postura, la energía (movimiento fuerte o suave) y la velocidad.","La plasticidad es la capacidad del cuerpo de tomar muchas formas; la intencionalidad es lo que quieres comunicar con cada movimiento.","Una secuencia de movimiento tiene inicio (posición quieta), desarrollo y final (posición quieta), y se puede contar en estructuras de 8 tiempos."],"media":{"id":"s03-ef-2-expresion","kind":"video","title":"El cuerpo que comunica","aspect":"16:9","duration":50,"alt":"Una niña representa la milpa: empieza agachada en nivel bajo como semilla, crece lentamente hasta nivel alto con los brazos como hojas, se mueve en curva con el viento y cae suave con la cosecha.","brief":"Video de 50 s en un salón despejado con luz natural. Una niña y un niño (ropa sencilla, rostros visibles solo con permiso o en silueta) interpretan \\"El ciclo de la milpa\\" sin palabras, con marimba suave de fondo: (1) semilla en nivel bajo, cuerpo cerrado; (2) crecimiento lento a nivel medio y alto; (3) viento: trayectoria curva, balanceo; (4) lluvia fuerte: movimientos rápidos y enérgicos en zigzag; (5) cosecha: caída suave y pausa final. Rótulos breves: \\"nivel bajo\\", \\"lento\\", \\"curva\\", \\"energía fuerte\\", \\"posición final\\". Ninguna vestimenta de una comunidad concreta. Accesibilidad: subtitulos completos para toda voz y transcripcion audiovisual; rotulos grandes, legibles y de alto contraste."},"steps":[{"fase":"explorar","areas":["ef"],"cnb":["ef:1.4.2"],"ambito":"conocer","title":"El cuerpo en el espacio y el tiempo","prompt":"Para moverte con intención, piensa **dónde** y **cuándo** te mueves. Toca cada tarjeta y pruébalo.","type":"explain","props":{"icon":"Compass","body":"Estas son las **relaciones espacio-temporales**: los \\"ingredientes\\" de cualquier movimiento.","reveal":[{"icon":"Compass","front":"Direcciones","back":"Adelante, atrás, a la derecha, a la izquierda, arriba y abajo."},{"icon":"Layers","front":"Niveles","back":"**Bajo** (en el suelo, en cuclillas), **medio** (rodillas dobladas, inclinado) y **alto** (de pie, de puntillas, saltando)."},{"icon":"Route","front":"Trayectorias","back":"El camino que dibujas en el suelo: **recta**, **curva**, **zigzag**, **círculo**."},{"icon":"Timer","front":"Velocidad y duración","back":"Rápido o lento, largo o corto. Puedes moverte **en 8 tiempos** o **en 2**, y eso cambia la sensación."}]},"id":"s03-ef-2-1"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.12"],"ambito":"conocer","prompt":"En el video, la niña empieza **agachada, cerrada y quieta**. ¿Qué crees que representa?","explain":"Una **semilla**. Sin palabras, usó el **nivel bajo**, la **postura cerrada** y la **quietud**. El cuerpo es un lenguaje: hoy aprenderás sus \\"palabras\\".","type":"choice","props":{"options":[{"id":"a","text":"Una semilla bajo la tierra","icon":"Sprout"},{"id":"b","text":"Una persona corriendo","icon":"Footprints","feedback":"Correr necesita movimiento y desplazamiento; ella está quieta y en el suelo."},{"id":"c","text":"Un árbol muy alto","icon":"TreePine","feedback":"Un árbol alto usaría el nivel alto, con el cuerpo estirado."}],"correct":["a"]},"id":"s03-ef-2-2"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.12"],"ambito":"conocer","title":"Los recursos expresivos","prompt":"Actores, danzantes y deportistas usan el cuerpo para **comunicar**. Toca cada recurso.","type":"explain","props":{"icon":"Smile","body":"La **plasticidad** es la capacidad del cuerpo de tomar muchas formas. La **intencionalidad** es **lo que quieres decir** con cada forma.","reveal":[{"icon":"Smile","front":"Gesto","back":"Lo que hacen la **cara** y las **manos**: sonreír, fruncir el ceño, abrir las palmas."},{"icon":"Eye","front":"Mirada","back":"A dónde miras dice mucho: arriba (esperanza), abajo (tristeza o timidez), al público (seguridad)."},{"icon":"PersonStanding","front":"Postura","back":"Cuerpo **abierto** y erguido (alegría, fuerza) o **cerrado** y encogido (miedo, frío, tristeza)."},{"icon":"Zap","front":"Energía","back":"Movimiento **fuerte** y cortante (enojo, tormenta) o **suave** y fluido (calma, agua, viento)."},{"icon":"Gauge","front":"Velocidad","back":"**Rápido** transmite prisa, emoción o nervios; **lento**, calma, cansancio o solemnidad."}]},"id":"s03-ef-2-3"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.2","ef:1.4.12"],"ambito":"hacer","title":"Ejemplo resuelto: la secuencia \\"El volcán despierta\\"","prompt":"Mira cómo Julio arma una secuencia de **4 partes de 8 tiempos** con una intención clara.","type":"worked-example","props":{"icon":"Mountain","problem":"Julio quiere mostrar, sin palabras, un volcán que duerme, despierta, hace erupción y vuelve a la calma.","steps":[{"text":"**Inicio (8 tiempos):** nivel **bajo**, postura cerrada, quieto; solo respira despacio. Intención: el volcán duerme."},{"text":"**Parte 2 (8 tiempos):** sube **lentamente** al nivel medio, temblando un poco los brazos. Intención: el volcán despierta.","why":"La velocidad lenta y el temblor crean suspenso."},{"text":"**Parte 3 (8 tiempos):** salta al nivel **alto**, brazos que se abren **rápido y con energía fuerte** hacia arriba y en **zigzag**. Intención: la erupción."},{"text":"**Final (8 tiempos):** baja en **trayectoria curva**, con movimientos **suaves**, hasta quedar quieto en nivel bajo. Intención: la lava se enfría y vuelve la calma."}],"answer":"Julio combinó **niveles, velocidad, energía y trayectorias** con una **intención** clara en cada parte, en 4 × 8 = 32 tiempos.","tip":"Empieza y termina siempre con una posición quieta: el público entiende dónde empieza y dónde acaba la historia."},"id":"s03-ef-2-4"},{"fase":"construir","areas":["ef"],"cnb":["ef:1.4.12"],"ambito":"hacer","prompt":"Une cada idea que quieres comunicar con el recurso expresivo que mejor la muestra.","hint":"Piensa en la postura, la energía y la velocidad de cada emoción.","explain":"Cada recurso tiene una intención: la postura cerrada comunica frío o miedo, la energía fuerte enojo o fuerza, la lentitud calma o cansancio.","type":"match","props":{"leftTitle":"Quiero comunicar…","rightTitle":"Recurso","pairs":[{"id":"f","left":"Tengo mucho frío","right":"Postura cerrada y temblorosa"},{"id":"t","left":"Llega una tormenta","right":"Energía fuerte y movimientos rápidos"},{"id":"c","left":"El agua del lago en calma","right":"Movimientos suaves, lentos y curvos"},{"id":"a","left":"¡Ganamos el partido!","right":"Postura abierta, brazos arriba y sonrisa"}]},"id":"s03-ef-2-5"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.4.2","ef:1.4.12"],"ambito":"hacer","prompt":"¡Tu secuencia! **Calentamiento:** muévete por el espacio en trayectoria recta, curva y zigzag (20 s cada una), cambiando de nivel cuando alguien diga \\"¡bajo!\\", \\"¡medio!\\", \\"¡alto!\\". **Parte principal:** crea tu propia secuencia de **4 partes de 8 tiempos** sobre uno de estos temas: \\"La milpa crece\\", \\"Un día de lluvia\\" o \\"El río baja de la montaña\\". Usa al menos 2 niveles, 2 trayectorias y cambios de velocidad. Repítela 3 veces hasta que te salga fluida y muéstrasela a alguien. **Poco espacio:** usa más los niveles que el desplazamiento. **Adaptación:** en silla de ruedas, usa brazos, tronco, cabeza y giros de la silla. **Vuelta a la calma:** estira y respira.","type":"pulse-lab","props":{"seconds":15,"rounds":[{"label":"En reposo"},{"label":"Después del calentamiento en el espacio","exercise":{"name":"Trayectorias y niveles","icon":"Route","seconds":60}},{"label":"Después de tu secuencia (3 veces)","exercise":{"name":"Secuencia expresiva de 4 × 8 tiempos","icon":"Sparkles","seconds":90}}]},"id":"s03-ef-2-6"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.4.2","ef:1.4.12"],"ambito":"hacer","prompt":"Escribe el **guion de tu secuencia**: el tema, y en cada una de las 4 partes de 8 tiempos, qué **nivel**, **trayectoria**, **velocidad** y **energía** usaste y qué querías **comunicar**.","type":"short-answer","props":{"minWords":40,"placeholder":"Mi tema es… Parte 1: … Parte 2: … Parte 3: … Parte 4: …","model":"Mi tema es \\"El río baja de la montaña\\". Parte 1: nivel alto, de puntillas, movimientos suaves; soy el agua que nace arriba. Parte 2: nivel medio, trayectoria en zigzag y más rápido; el río baja entre piedras. Parte 3: nivel bajo, energía fuerte, brazos que empujan; es una crecida por la lluvia. Parte 4: trayectoria curva, lento y suave hasta quedar quieta; el río llega tranquilo al lago.","rubric":["Tiene un tema claro","Describe 4 partes de 8 tiempos","Usa al menos 2 niveles y 2 trayectorias","Explica la intención de cada parte"]},"id":"s03-ef-2-7"},{"fase":"aplicar","areas":["ef"],"cnb":["ef:1.4.2","ef:1.4.12"],"ambito":"hacer","prompt":"Para representar a una persona que avanza con cautela por una ruta estrecha, ¿qué secuencia comunica mejor esa intención?","type":"choice","props":{"options":[{"id":"a","text":"Pasos lentos en línea curva, nivel medio, mirada al frente y energía suave"},{"id":"b","text":"Saltos rápidos sin mirar, con giros amplios y energía fuerte"},{"id":"c","text":"Quedarse inmóvil de espaldas durante toda la secuencia"}],"correct":["a"]},"id":"s03-ef-2-8"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.4.2"],"prompt":"Te mueves **en cuclillas**, con las rodillas muy dobladas y las manos cerca del suelo. ¿En qué nivel estás?","type":"choice","props":{"options":[{"id":"a","text":"Nivel alto"},{"id":"b","text":"Nivel medio"},{"id":"c","text":"Nivel bajo"}],"correct":["c"]},"id":"s03-ef-2-9"},{"fase":"comprobar","areas":["ef"],"cnb":["ef:1.4.2","ef:1.4.12"],"prompt":"Clasifica cada elemento: ¿es una **relación espacio-temporal** o un **recurso expresivo**?","type":"sort","props":{"buckets":[{"id":"e","label":"Espacio-tiempo","icon":"Compass","color":"var(--area-ef)"},{"id":"x","label":"Recurso expresivo","icon":"Smile","color":"var(--c-maiz-strong)"}],"items":[{"id":"y1","text":"Trayectoria en zigzag","bucket":"e"},{"id":"y2","text":"Mirada hacia abajo","bucket":"x"},{"id":"y3","text":"Nivel alto","bucket":"e"},{"id":"y4","text":"Gesto de sorpresa","bucket":"x"},{"id":"y5","text":"Postura encogida","bucket":"x"}]},"id":"s03-ef-2-10"},{"fase":"reflexionar","ambito":"ser","prompt":"¿Cómo te fue? Responde con sinceridad: aprender es un camino.","areas":["ef"],"cnb":["ef:1.4.12"],"type":"reflection","props":{"statements":["Marcho y troto siguiendo el pulso de la música","Uso niveles, direcciones y trayectorias","Comunico una idea con gestos, postura, energía y velocidad"],"commitments":["Practicaré mi patrón de 8 tiempos con una canción","Presentaré mi secuencia a mi familia","Observaré cómo se mueven los danzantes en las fiestas de mi comunidad"]},"id":"s03-ef-2-11"}],"kind":"materia","area":"ef","day":5}},{"missionId":"s03","version":"cnb-sexto-1e4a577649fb6dc8","lesson":{"id":"s03-cnt-1","title":"Vertebrados e invertebrados","icon":"Bird","minutes":15,"gancho":"Pasa la mano por el centro de tu espalda: sientes una fila de huesitos. ¿Cuáles animales tienen algo así y cuáles no?","objetivos":["Clasificar animales como vertebrados o invertebrados mediante rasgos observables y una clave sencilla"],"resumen":["Los vertebrados tienen columna vertebral y un esqueleto interno. Son cinco grupos: peces, anfibios, reptiles, aves y mamíferos.","Los invertebrados no tienen columna vertebral. Son la gran mayoría de las especies animales: artrópodos (insectos, arácnidos, crustáceos), moluscos, anélidos (lombrices), equinodermos y medusas, entre otros.","Muchos invertebrados tienen un esqueleto externo (exoesqueleto) o una concha; otros tienen el cuerpo blando."],"media":{"id":"s03-cnt-1-sendero","kind":"image","title":"Un sendero lleno de animales","aspect":"16:9","alt":"Ilustración de un sendero en un bosque nuboso de Guatemala con un quetzal, una iguana, una rana, un venado, una mariposa morpho, un caracol, una tarántula, una lombriz y un río con una mojarra.","brief":"Ilustración horizontal y detallada de un sendero de bosque nuboso guatemalteco (helechos, bromelias, musgo, río pequeño). Incluir, bien visibles y en proporciones realistas: quetzal en una rama, iguana en una piedra, rana verde junto al río, venado cola blanca al fondo, mojarra en el agua, mariposa azul, caracol sobre una hoja, tarántula junto a una raíz, lombriz de tierra en el suelo húmedo, hormigas en fila. Sin rótulos (el estudiante los identifica). Colores naturales, estilo de guía de naturaleza para niños. Dimensiones: 1600x900. Accesibilidad: contraste alto, rotulos grandes y legibles; la descripcion visual debe corresponder exactamente al texto alternativo."},"steps":[{"fase":"explorar","areas":["cnt"],"cnb":["cnt:2.1.2"],"ambito":"conocer","title":"Con columna o sin columna","prompt":"Una forma de organizar a los animales es preguntarse: **¿tiene columna vertebral?** Toca las tarjetas.","type":"explain","props":{"icon":"Bone","body":"La **columna vertebral** es una fila de huesos llamados **vértebras** que sostiene el cuerpo y protege la médula espinal.","reveal":[{"icon":"Bone","front":"Vertebrados","back":"Tienen **columna vertebral** y **esqueleto interno** (huesos dentro del cuerpo), y un cráneo que protege el cerebro. Ejemplos: quetzal, jaguar, iguana, tú."},{"icon":"Bug","front":"Invertebrados","back":"**No** tienen columna vertebral. Algunos tienen un **esqueleto externo** duro (exoesqueleto), otros una **concha** y otros el cuerpo **blando**."},{"icon":"BarChart3","front":"¿Cuántos hay?","back":"Los invertebrados son **la gran mayoría** de las especies animales del planeta: solo los insectos son muchísimas más especies que todos los vertebrados juntos."}]},"id":"s03-cnt-1-1"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.1.2"],"ambito":"conocer","prompt":"Mira el sendero de la imagen. ¿Cuál de estos animales tiene una **columna vertebral** como la tuya?","explain":"La **iguana** tiene columna vertebral y esqueleto interno. El caracol y la mariposa no tienen huesos.","type":"choice","props":{"layout":"grid","options":[{"id":"a","text":"Caracol","icon":"Shell","feedback":"El caracol tiene cuerpo blando y una concha, pero no huesos."},{"id":"b","text":"Iguana","icon":"Footprints"},{"id":"c","text":"Mariposa","icon":"Bug","feedback":"La mariposa tiene un esqueleto externo, duro y delgado, pero no columna vertebral."}],"correct":["b"]},"id":"s03-cnt-1-2"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.1.2"],"ambito":"conocer","prompt":"Organiza a los animales del sendero en **vertebrados** e **invertebrados**.","hint":"Pregúntate: ¿tiene huesos por dentro? Si tiene concha, exoesqueleto o cuerpo blando, es invertebrado.","explain":"Quetzal, rana, mojarra, venado e iguana tienen columna. Tarántula, caracol, lombriz y hormiga no.","type":"sort","props":{"buckets":[{"id":"v","label":"Vertebrado","icon":"Bone","color":"var(--area-cnt)"},{"id":"i","label":"Invertebrado","icon":"Bug","color":"var(--c-maiz-strong)"}],"items":[{"id":"a1","text":"Quetzal","bucket":"v"},{"id":"a2","text":"Tarántula","bucket":"i"},{"id":"a3","text":"Rana","bucket":"v"},{"id":"a4","text":"Caracol","bucket":"i"},{"id":"a5","text":"Mojarra","bucket":"v"},{"id":"a6","text":"Lombriz de tierra","bucket":"i"},{"id":"a7","text":"Venado","bucket":"v"},{"id":"a8","text":"Hormiga","bucket":"i"}]},"id":"s03-cnt-1-3"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.1.2"],"ambito":"conocer","title":"Los cinco grupos de vertebrados","prompt":"Los vertebrados se organizan en **cinco grupos**. Fíjate en la **piel** y en **cómo respiran y nacen**. Toca cada tarjeta.","media":{"id":"s03-cnt-1-vertebrados","kind":"diagram","title":"Cinco grupos de vertebrados de Guatemala","aspect":"16:9","alt":"Cinco columnas: mojarra (pez), rana (anfibio), iguana (reptil), quetzal (ave) y jaguar (mamífero), con íconos de su cubierta del cuerpo, forma de respirar y forma de nacer.","brief":"Infografía de 5 columnas con un animal guatemalteco cada una: mojarra, rana, iguana, quetzal, jaguar. Debajo de cada uno tres íconos con texto corto: cubierta (escamas húmedas / piel húmeda / escamas secas / plumas / pelo), respiración (branquias / branquias de renacuajo y pulmones de adulto / pulmones / pulmones / pulmones) y nacimiento (huevos en agua / huevos en agua / huevos con cáscara en tierra / huevos con cáscara / la mayoría nace del vientre y toma leche). Colores planos, letra grande. Dimensiones: 1600x900."},"type":"explain","props":{"icon":"Bird","body":"Todos tienen columna, pero se diferencian por su cubierta, su respiración y su forma de nacer.","reveal":[{"icon":"Fish","front":"Peces","back":"Viven en el agua, respiran por **branquias**, tienen **escamas** y **aletas**. Ejemplo: la mojarra."},{"icon":"Droplets","front":"Anfibios","back":"**Piel húmeda sin escamas**. Nacen en el agua (renacuajos con branquias) y de adultos respiran con **pulmones** y por la piel. Ejemplo: la rana."},{"icon":"Footprints","front":"Reptiles","back":"Piel con **escamas secas**; respiran con pulmones; ponen **huevos con cáscara** en tierra. Ejemplos: iguana, tortuga, cocodrilo, serpiente."},{"icon":"Feather","front":"Aves","back":"Cuerpo cubierto de **plumas**, pico, alas y huevos con cáscara dura. Ejemplo: el quetzal, ave nacional."},{"icon":"Cat","front":"Mamíferos","back":"Tienen **pelo** y las madres **amamantan** a sus crías con leche. Casi todos nacen del vientre. Ejemplos: jaguar, manatí, murciélago, ser humano."}]},"id":"s03-cnt-1-4"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.1.2"],"ambito":"conocer","prompt":"Une cada animal con su grupo de vertebrados.","hint":"Fíjate en la cubierta del cuerpo: plumas, pelo, escamas secas, piel húmeda o escamas con aletas.","explain":"Tortuga: escamas secas → reptil. Tucán: plumas → ave. Manatí: amamanta → mamífero. Salamandra: piel húmeda → anfibio. Tiburón: branquias y aletas → pez.","type":"match","props":{"leftTitle":"Animal","rightTitle":"Grupo","pairs":[{"id":"t","left":"Tortuga marina","right":"Reptil"},{"id":"u","left":"Tucán","right":"Ave"},{"id":"m","left":"Manatí","right":"Mamífero"},{"id":"s","left":"Salamandra","right":"Anfibio"},{"id":"b","left":"Tiburón","right":"Pez"}]},"id":"s03-cnt-1-5"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.1.2"],"ambito":"conocer","title":"Los grupos de invertebrados","prompt":"Los invertebrados son muy variados. Conoce los grupos más comunes. Toca las tarjetas.","type":"explain","props":{"icon":"Bug","body":"El grupo más grande es el de los **artrópodos**: tienen **patas articuladas** (con \\"coyunturas\\") y un **exoesqueleto**.","reveal":[{"icon":"Bug","front":"Insectos","back":"Artrópodos con **6 patas** y el cuerpo en 3 partes (cabeza, tórax, abdomen). Muchos tienen alas. Ejemplos: hormiga, abeja, mariposa."},{"icon":"Bug","front":"Arácnidos","back":"Artrópodos con **8 patas** y sin antenas. Ejemplos: araña, tarántula, alacrán, garrapata."},{"icon":"Shell","front":"Crustáceos y miriápodos","back":"**Crustáceos**: cangrejo y camarón (muchas patas, casi todos acuáticos). **Miriápodos**: ciempiés, con muchísimas patas."},{"icon":"Shell","front":"Moluscos","back":"Cuerpo **blando**; muchos tienen **concha**. Ejemplos: caracol, jute, almeja, pulpo (sin concha)."},{"icon":"Route","front":"Anélidos","back":"Cuerpo blando formado por **anillos**. Ejemplo: la lombriz de tierra, que ayuda a airear el suelo."},{"icon":"Star","front":"Otros","back":"**Equinodermos** (estrella de mar), **medusas** y **esponjas** de mar."}]},"id":"s03-cnt-1-6"},{"fase":"construir","areas":["cnt"],"cnb":["cnt:2.1.2"],"ambito":"hacer","title":"Ejemplo: clasificar con una clave","prompt":"Los científicos usan **claves**: preguntas de sí o no que llevan paso a paso al grupo del animal. Mira cómo se usa.","type":"worked-example","props":{"icon":"Search","problem":"En el patio, Josué encuentra un animal pequeño con **8 patas** articuladas y sin antenas. ¿A qué grupo pertenece?","steps":[{"text":"Pregunta 1: ¿tiene columna vertebral? **No**, su cuerpo es duro por fuera → es **invertebrado**."},{"text":"Pregunta 2: ¿tiene patas articuladas y exoesqueleto? **Sí** → es un **artrópodo**.","why":"Moluscos y anélidos no tienen patas articuladas."},{"text":"Pregunta 3: ¿cuántas patas tiene? **8** y no tiene antenas → es un **arácnido**.","why":"Los insectos tienen 6 patas; los arácnidos, 8."}],"answer":"Es un **arácnido** (por ejemplo, una araña): invertebrado → artrópodo → arácnido.","tip":"Cuenta siempre las patas con cuidado… ¡y observa sin tocar a los animales que no conoces!"},"id":"s03-cnt-1-7"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:2.1.2"],"ambito":"conocer","prompt":"El **murciélago** vuela y tiene alas. ¿En qué grupo lo clasificas?","explain":"Aunque vuela, el murciélago tiene **pelo** y las madres **amamantan** a sus crías: es un **mamífero**.","type":"choice","props":{"options":[{"id":"a","text":"Ave, porque vuela","icon":"Feather","feedback":"Volar no define a las aves: las aves tienen plumas. El murciélago tiene pelo."},{"id":"b","text":"Mamífero, porque tiene pelo y amamanta","icon":"Cat"},{"id":"c","text":"Insecto, porque tiene alas","icon":"Bug","feedback":"Los insectos no tienen columna vertebral; el murciélago sí."}],"correct":["b"]},"id":"s03-cnt-1-8"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:2.1.2"],"ambito":"conocer","prompt":"Un animal tiene **piel húmeda sin escamas**, pone huevos en el agua y, cuando es pequeño, respira por **branquias**. ¿Qué es?","explain":"Piel húmeda, huevos en agua y una etapa con branquias: es un **anfibio**, como la rana o la salamandra.","type":"choice","props":{"options":[{"id":"a","text":"Un pez","feedback":"Los peces tienen escamas y respiran por branquias toda la vida."},{"id":"b","text":"Un reptil","feedback":"Los reptiles tienen escamas secas y ponen huevos con cáscara en tierra."},{"id":"c","text":"Un anfibio"}],"correct":["c"]},"id":"s03-cnt-1-9"},{"fase":"aplicar","areas":["cnt"],"cnb":["cnt:2.1.2"],"ambito":"hacer","prompt":"Usa lo aprendido: clasifica cada invertebrado en su grupo.","explain":"Insectos: 6 patas. Arácnidos: 8 patas. Moluscos: cuerpo blando, a veces con concha. Anélidos: cuerpo en anillos.","type":"sort","props":{"buckets":[{"id":"ins","label":"Insecto (6 patas)","icon":"Bug","color":"var(--area-cnt)"},{"id":"ara","label":"Arácnido (8 patas)","icon":"Bug","color":"var(--area-ccss)"},{"id":"mol","label":"Molusco","icon":"Shell","color":"var(--c-maiz-strong)"},{"id":"ane","label":"Anélido","icon":"Route","color":"var(--area-art)"}],"items":[{"id":"b1","text":"Abeja","bucket":"ins"},{"id":"b2","text":"Alacrán","bucket":"ara"},{"id":"b3","text":"Jute (caracol de río)","bucket":"mol"},{"id":"b4","text":"Lombriz de tierra","bucket":"ane"},{"id":"b5","text":"Zancudo","bucket":"ins"},{"id":"b6","text":"Pulpo","bucket":"mol","feedback":"El pulpo no tiene concha, pero es un molusco de cuerpo blando."},{"id":"b7","text":"Garrapata","bucket":"ara","feedback":"La garrapata tiene 8 patas: es un arácnido, no un insecto."}]},"id":"s03-cnt-1-10"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:2.1.2"],"prompt":"¿Cuál de estos animales es **invertebrado**?","type":"choice","props":{"options":[{"id":"a","text":"La serpiente"},{"id":"b","text":"El pulpo"},{"id":"c","text":"La rana"},{"id":"d","text":"El murciélago"}],"correct":["b"]},"id":"s03-cnt-1-11"},{"fase":"comprobar","areas":["cnt"],"cnb":["cnt:2.1.2"],"prompt":"¿Verdadero o falso?","type":"true-false","props":{"statements":[{"text":"Los insectos tienen 6 patas y los arácnidos tienen 8.","answer":true},{"text":"Los vertebrados son la mayoría de las especies animales del planeta.","answer":false,"why":"La gran mayoría de especies son invertebrados."},{"text":"Las aves son los únicos vertebrados con plumas.","answer":true},{"text":"La tortuga es un anfibio porque vive en el agua.","answer":false,"why":"La tortuga tiene escamas y pone huevos con cáscara en tierra: es un reptil."}]},"id":"s03-cnt-1-12"}],"kind":"materia","area":"cnt","day":1}}]'),o={mission:e,lessons:a};export{o as default,a as lessons,e as mission};
